// === Tab: MazeGeneration ===
function generateMazeChunk(width, height, chunkX, chunkZ) {

    const noiseScale = 0.1;
    const nVal = noise(chunkX * noiseScale, chunkZ * noiseScale);

    let roomType;

    if (nVal < 0.15) {
        roomType = ROOM_TYPE_DUNGEON;
    } else if (nVal < 0.3) {
        roomType = ROOM_TYPE_OPEN_ROOM;
    } else if (nVal < 0.45) {
        roomType = ROOM_TYPE_COLUMNS;
    } else if (nVal < 0.6) {
        roomType = ROOM_TYPE_CORRIDOR;
    } else if (nVal < 0.8) {
        roomType = ROOM_TYPE_MAZE;
    } else {
        roomType = ROOM_TYPE_DEAD_END;
    }

    const seed = computeHash(chunkX, chunkZ);
    randomSeed(seed);
    noiseSeed(seed);

    let maze;
    switch (roomType) {
        case ROOM_TYPE_CORRIDOR:
            maze = generateCorridor(width, height);
            break;
        case ROOM_TYPE_OPEN_ROOM:
            maze = generateOpenRoom(width, height);
            break;
        case ROOM_TYPE_COLUMNS:
            maze = generateColumnsRoom(width, height);
            break;
        case ROOM_TYPE_MAZE:
            maze = generateMazeRoom(width, height);
            break;
        case ROOM_TYPE_DEAD_END:
            maze = generateDeadEnd(width, height);
            break;
        case ROOM_TYPE_DUNGEON:
            maze = generateDungeonRoom(width, height);
            break;
        default:
            maze = generateOpenRoom(width, height);
            break;
    }

    maze = ensureConnectivity(maze, width, height);

    let dissolveState = Array.from(Array(width), () => Array(height).fill(0.0));

    return {
        maze: maze,
        dissolveState: dissolveState, 
        roomType: roomType,
        wallHeight: wallHeight,
        chunkX: chunkX,
        chunkZ: chunkZ
    };
}

function generateCorridor(width, height) {
    const maze = Array.from(Array(width), () => Array(height).fill(1));
    const horizontal = random() < 0.5; 
    if (horizontal) {
        const corridorY = floor(height / 2);
        for (let i = 0; i < width; i++) {
            maze[i][corridorY] = 0;
        }
    } else {
        const corridorX = floor(width / 2);
        for (let j = 0; j < height; j++) {
            maze[corridorX][j] = 0;
        }
    }

    connectEdgeOpenings(maze, width, height, true, true, true, true);
    return maze;
}

function generateOpenRoom(width, height) {
    const maze = Array.from(Array(width), () => Array(height).fill(0));

    if (random() < 0.5) {

        const centerX = floor(width / 2);
        for (let j = 2; j < height - 2; j += 3) {
            maze[centerX][j] = 1;
        }
    } else {

        for (let i = 2; i < width - 2; i += 3) {
            maze[i][2] = 1;
            maze[i][height - 3] = 1;
        }
    }

    connectEdgeOpenings(maze, width, height, true, true, true, true);
    return maze;
}

function generateColumnsRoom(width, height) {
    const maze = Array.from(Array(width), () => Array(height).fill(0));
    const spacing = 3;
    for (let i = 1; i < width - 1; i++) {
        for (let j = 1; j < height - 1; j++) {
            if (i % spacing === 0 && j % spacing === 0) {
                if (random() < 0.8) {
                    maze[i][j] = 1;
                }
            }
        }
    }

    connectEdgeOpenings(maze, width, height, true, true, true, true);
    return maze;
}

function generateMazeRoom(width, height) {

    if (width % 2 === 0) width -= 1;
    if (height % 2 === 0) height -= 1;

    const maze = Array.from(Array(width), () => Array(height).fill(1));
    const visited = Array.from(Array(width), () => Array(height).fill(false));
    generateMazeRecursiveBacktracker(maze, visited, 1, 1);

    connectEdgeOpenings(maze, width, height, true, true, true, true);
    return maze;
}

function generateMazeRecursiveBacktracker(maze, visited, cx, cy) {
    const width = maze.length;
    const height = maze[0].length;

    visited[cx][cy] = true;
    maze[cx][cy] = 0;

    let dirs = [0, 1, 2, 3];
    dirs = shuffle(dirs, true); 

    for (let i = 0; i < dirs.length; i++) {
        let nx = cx;
        let ny = cy;

        switch (dirs[i]) {
            case 0: ny -= 2; break; 
            case 1: nx += 2; break; 
            case 2: ny += 2; break; 
            case 3: nx -= 2; break; 
        }

        if (nx >= 1 && nx <= width - 2 && ny >= 1 && ny <= height - 2 && !visited[nx][ny]) {
            maze[Math.floor((cx + nx) / 2)][Math.floor((cy + ny) / 2)] = 0;
            generateMazeRecursiveBacktracker(maze, visited, nx, ny);
        }
    }
}

function generateDeadEnd(width, height) {
    const maze = Array.from(Array(width), () => Array(height).fill(1));

    let x = floor(width / 2);
    let y = height - 1;
    while (y >= 0) {
        maze[x][y] = 0;
        y--;
    }

    connectEdgeOpenings(maze, width, height, false, false, false, true);
    return maze;
}

function generateDungeonRoom(width, height) {
    const maze = Array.from(Array(width), () => Array(height).fill(1));

    const centerX = floor(width / 2);
    const centerY = floor(height / 2);
    maze[centerX][centerY] = 0;

    let corridorLength = floor(max(width, height) / 3);
    for (let i = 1; i <= corridorLength; i++) {
        if (centerX - i >= 0) maze[centerX - i][centerY] = 0;
        if (centerX + i < width) maze[centerX + i][centerY] = 0;
        if (centerY - i >= 0) maze[centerX][centerY - i] = 0;
        if (centerY + i < height) maze[centerX][centerY + i] = 0;
    }

    for (let i = 0; i < 5; i++) {
        const rx = centerX + floor(random(-corridorLength, corridorLength));
        const ry = centerY + floor(random(-corridorLength, corridorLength));
        if (rx > 1 && rx < width - 1 && ry > 1 && ry < height - 1) {
            maze[rx][ry] = 0;

            if (random() < 0.7 && rx + 1 < width - 1) maze[rx + 1][ry] = 0;
            if (random() < 0.7 && rx - 1 > 1) maze[rx - 1][ry] = 0;
            if (random() < 0.7 && ry + 1 < height - 1) maze[rx][ry + 1] = 0;
            if (random() < 0.7 && ry - 1 > 1) maze[rx][ry - 1] = 0;
        }
    }

    connectEdgeOpenings(maze, width, height, true, true, true, true);
    return maze;
}

function ensureConnectivity(maze, width, height) {

    let startX = null;
    let startY = null;
    outerSearch:
    for (let i = 0; i < width; i++) {
        if (maze[i][0] === 0) { startX = i; startY = 0; break outerSearch; }
        if (maze[i][height - 1] === 0) { startX = i; startY = height - 1; break outerSearch; }
    }
    for (let j = 0; j < height; j++) {
        if (startX !== null) break;
        if (maze[0][j] === 0) { startX = 0; startY = j; break; }
        if (maze[width - 1][j] === 0) { startX = width - 1; startY = j; break; }
    }

    if (startX === null || startY === null) {
        maze[floor(width/2)][0] = 0;
        startX = floor(width/2);
        startY = 0;
    }

    let visited = Array.from(Array(width), () => Array(height).fill(false));
    let stack = [[startX, startY]];
    visited[startX][startY] = true;

    while (stack.length > 0) {
        const [cx, cy] = stack.pop();

        const neighbors = [
            [cx+1, cy], [cx-1, cy], [cx, cy+1], [cx, cy-1]
        ];
        for (let n of neighbors) {
            const nx = n[0];
            const ny = n[1];

            if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                if (!visited[nx][ny] && maze[nx][ny] === 0) {
                    visited[nx][ny] = true;
                    stack.push([nx, ny]);
                }
            }
        }
    }

    for (let i = 0; i < width; i++) {
        for (let j = 0; j < height; j++) {
            if (maze[i][j] === 0 && !visited[i][j]) {

                let nearestDist = Infinity;
                let nearestCell = null;
                for (let x = 0; x < width; x++) {
                    for (let y = 0; y < height; y++) {
                        if (visited[x][y] && maze[x][y] === 0) {
                            let d = abs(x - i) + abs(y - j);
                            if (d < nearestDist) {
                                nearestDist = d;
                                nearestCell = [x, y];
                            }
                        }
                    }
                }
                if (nearestCell) {

                    let sx = nearestCell[0];
                    let sy = nearestCell[1];
                    while (sx !== i || sy !== j) {
                        if (sx < i) sx++;
                        else if (sx > i) sx--;
                        if (sy < j) sy++;
                        else if (sy > j) sy--;

                        maze[sx][sy] = 0;
                        visited[sx][sy] = true;
                    }
                }
            }
        }
    }

    return maze;
}

function connectEdgeOpenings(maze, width, height, openLeft, openRight, openTop, openBottom) {
    if (openLeft) {
        let openingPos = floor(height / 2);
        maze[0][openingPos] = 0;
    }

    if (openRight) {
        let openingPos = floor(height / 2);
        maze[width - 1][openingPos] = 0;
    }

    if (openTop) {
        let openingPos = floor(width / 2);
        maze[openingPos][0] = 0;
    }

    if (openBottom) {
        let openingPos = floor(width / 2);
        maze[openingPos][height - 1] = 0;
    }
}

function computeHash(x, z) {
    let h = 31;
    h = h * 17 + x;
    h = h * 17 + z;
    return h;
}

function drawMaze() {
    noStroke();
    const floorFlickerOffset = 0.5;
    let dtSeconds = deltaTime / 1000.0;

    for (const key in mazeChunks) {
        const chunk = mazeChunks[key];
        const chunkX = chunk.chunkX;
        const chunkZ = chunk.chunkZ;

        let chunkAABB = getChunkAABB(chunkX, chunkZ);
        let isVisible = isBoxInFrustum(chunkAABB, currentFrustumPlanes);

        if (isVisible) {
            const baseX = chunkX * chunkSize * cellSize;
            const baseZ = chunkZ * chunkSize * cellSize;

            push();
            translate(baseX + (chunkSize * cellSize) / 2, 0, baseZ + (chunkSize * cellSize) / 2);
            rotateX(-HALF_PI);
            texture(ceilingTexture);
            plane(chunkSize * cellSize, chunkSize * cellSize);
            pop();
        }
    }

    for (const key in mazeChunks) {
        const chunk = mazeChunks[key];
        const chunkX = chunk.chunkX;
        const chunkZ = chunk.chunkZ;

        let chunkAABB = getChunkAABB(chunkX, chunkZ); 
        let isVisible = isBoxInFrustum(chunkAABB, currentFrustumPlanes);

        if (isVisible) {
            const maze = chunk.maze;
            const dissolveState = chunk.dissolveState;
            const baseX = chunkX * chunkSize * cellSize;
            const baseZ = chunkZ * chunkSize * cellSize;

            for (let i = 0; i < chunkSize; i++) {
                for (let j = 0; j < chunkSize; j++) {
                     if (maze[i][j] === 1 && dissolveState[i][j] < 1.0) {
                        const posX = baseX + (i + 0.5) * cellSize;
                        const posZ = baseZ + (j + 0.5) * cellSize;
                        const wallCenterY = (wallHeight - wallHeightOffset) / 2 + floorFlickerOffset;

                        if (wallPassActive && dissolveState[i][j] === 0.0) {
                            let distToWall = dist(player.x, player.z, posX, posZ);
                            if (distToWall < wallPassTriggerRadius) {
                                dissolveState[i][j] = 0.01;
                            }
                        }

                        let currentDissolveProgress = dissolveState[i][j];
                        let isDissolving = currentDissolveProgress > 0.0 && currentDissolveProgress < 1.0;

                        if (isDissolving) {
                            let effectiveDissolveRate = wallDissolveRate;
                            if (timeScale !== 0) {
                                effectiveDissolveRate *= (timeScale > 0 ? timeScale : (1.0 / Math.abs(timeScale)));
                            } else {
                                effectiveDissolveRate = 0;
                            }
                            currentDissolveProgress += effectiveDissolveRate * dtSeconds;
                            currentDissolveProgress = min(currentDissolveProgress, 1.0);
                            dissolveState[i][j] = currentDissolveProgress;
                        }

                        if (currentDissolveProgress < 1.0) {
                            push();
                            translate(posX, wallCenterY, posZ);

                            if (isDissolving) {
                                let edgeColor = [0.2, 0.8, 1.0];
                                shader(dissolveShader);
                                dissolveShader.setUniform('uWallTexture', wallTexture);
                                dissolveShader.setUniform('uNoiseTexture', noiseTexture);
                                dissolveShader.setUniform('uDissolveThreshold', currentDissolveProgress);
                                dissolveShader.setUniform('uEdgeColor', edgeColor);
                                dissolveShader.setUniform('uTime', millis() / 1000.0);
                                drawingContext.enable(drawingContext.BLEND);
                                drawingContext.blendFunc(drawingContext.SRC_ALPHA, drawingContext.ONE_MINUS_SRC_ALPHA);
                            } else {
                                texture(wallTexture);
                                drawingContext.disable(drawingContext.BLEND);
                            }

                            box(cellSize, wallHeight + wallHeightOffset, cellSize);

                            if (isDissolving) {
                                resetShader();
                            }
                            pop();
                        }
                    }
                }
            }
        }
    }

    for (const key in mazeChunks) {
        const chunk = mazeChunks[key];
        const chunkX = chunk.chunkX;
        const chunkZ = chunk.chunkZ;

        let chunkAABB = getChunkAABB(chunkX, chunkZ); 
        let isVisible = isBoxInFrustum(chunkAABB, currentFrustumPlanes);

        if (isVisible) {
            const baseX = chunkX * chunkSize * cellSize;
            const baseZ = chunkZ * chunkSize * cellSize;

            push();
            drawingContext.disable(drawingContext.BLEND);
            translate(baseX + (chunkSize * cellSize) / 2, wallHeight, baseZ + (chunkSize * cellSize) / 2);
            rotateX(HALF_PI);
            texture(floorTexture);
            plane(chunkSize * cellSize, chunkSize * cellSize);
            pop();
        }
    }
}

function updateMazeChunks() {
    const playerChunkX = floor(player.x / (cellSize * chunkSize));
    const playerChunkZ = floor(player.z / (cellSize * chunkSize));

    const keysToRemove = [];
    for (const key in mazeChunks) {
        const [chunkX, chunkZ] = key.split(",").map(Number);
        if (abs(chunkX - playerChunkX) > renderDistance ||
            abs(chunkZ - playerChunkZ) > renderDistance) {
            keysToRemove.push(key);
        }
    }
    for (const key of keysToRemove) {
        delete mazeChunks[key];
    }

    coins = coins.filter(coin => {
        const coinChunkX = floor(coin.x / (cellSize * chunkSize));
        const coinChunkZ = floor(coin.z / (cellSize * chunkSize));
        const coinKey = coinChunkX + "," + coinChunkZ;
        return !(keysToRemove.includes(coinKey));
    });

    for (let i = -renderDistance; i <= renderDistance; i++) {
        for (let j = -renderDistance; j <= renderDistance; j++) {
            const chunkX = playerChunkX + i;
            const chunkZ = playerChunkZ + j;
            const key = chunkX + "," + chunkZ;
            if (!(key in mazeChunks)) {

                const chunkData = generateMazeChunk(chunkSize, chunkSize, chunkX, chunkZ);
                mazeChunks[key] = chunkData;

                if (coinSpawnEnabled) {
                    spawnCoinsInChunk(chunkData);
                }
            }
        }
    }
}

function spawnCoinsInChunk(chunkData) {

    const { maze, chunkX, chunkZ } = chunkData;

    let attempts = floor(random(1, 4) * coinSpawnMultiplier);
    for (let a = 0; a < attempts; a++) {

        let rx = floor(random(chunkSize));
        let rz = floor(random(chunkSize));
        if (maze[rx][rz] === 0) {

            if (random(1) < 0.3 * coinSpawnMultiplier * baseCoinSpawnMultiplier) {
                const cellX = (chunkX * chunkSize + rx + 0.5) * cellSize;
                const cellZ = (chunkZ * chunkSize + rz + 0.5) * cellSize;

                coins.push({
                    x: cellX,
                    y: 150 + 20,
                    z: cellZ,
                    angle: random(TWO_PI)
                });
            }
        }
    }
}

// === Tab: InGameUi ===
let minimap;
const minimapSize = 200;
let minimapZoomUpgradeLevel = 0;
let minimapZoomLevel = 3;

const momentumMeterWidth = 30;
let momentumMeterPaddingX = 2100;
let momentumMeterPaddingY = 20;
let momentumMeterHeight;
let momentumMeterX;
let momentumMeterY;
let currentFillHeight = 0;

let slowMotionMeterX, slowMotionMeterY, slowMotionMeterHeight;
let slowMotionCurrentFillHeight = 0;

function initializeInGameUI() {
	minimap = createGraphics(minimapSize, minimapSize);
	minimap.pixelDensity(1);

	momentumMeterHeight = minimapSize;
	momentumMeterX = -width / 2 + minimapSize + momentumMeterPaddingX;
	momentumMeterY = -height / 2 + momentumMeterPaddingY;

	slowMotionMeterHeight = minimapSize;
	slowMotionMeterX = momentumMeterX - momentumMeterWidth - 20;
	slowMotionMeterY = momentumMeterY;

    prestigeItemPlaceholderImage = loadImage('https://openprocessing.org/sketch/2488820/files/comingsoon.png');
    prestigeItem1Image = loadImage('https://openprocessing.org/sketch/2488820/files/item1.png');
	prestigeItem2Image = loadImage('https://openprocessing.org/sketch/2488820/files/item2.png');
}

function drawInGameUI() {
	if (showMainMenu || playerDead) return;

	updateMinimap();
	drawMinimap();
	drawMomentumMeter();
	drawSlowMotionMeter();
	drawLivesIndicator();
	drawCoinsCollectedText();
	drawActionBar();

	if (isDebugModeOn) {
		drawDebugInfo();
	}
}

function updateMinimap() {
	minimap.background(50, 50, 50, 200);
	minimap.stroke(255);
	minimap.fill(100, 100, 100);

	const mapWidth = (renderDistance * 2 + 1) * chunkSize * cellSize;
	const zoomFactor = pow(1.5, minimapZoomLevel - 1);
	const scaleFactor = (minimapSize / mapWidth) * zoomFactor;

	minimap.push();
	minimap.translate(minimapSize / 2, minimapSize / 2);
	minimap.scale(-1, -1);
	minimap.rotate(-player.angleY + HALF_PI);

	for (const key in mazeChunks) {
		const chunk = mazeChunks[key];
		const chunkX = chunk.chunkX;
		const chunkZ = chunk.chunkZ;
		const maze = chunk.maze;

		const baseX = chunkX * chunkSize * cellSize;
		const baseZ = chunkZ * chunkSize * cellSize;

		for (let i = 0; i < chunkSize; i++) {
			for (let j = 0; j < chunkSize; j++) {
				if (maze[i][j] === 1) {
					const cellX = (baseX + (i + 0.5) * cellSize - player.x) * scaleFactor;
					const cellZ = (baseZ + (j + 0.5) * cellSize - player.z) * scaleFactor;

					minimap.rect(cellX, cellZ, cellSize * scaleFactor, cellSize * scaleFactor);
				}
			}
		}
	}

	minimap.fill(255, 0, 0);
	minimap.noStroke();
	minimap.ellipse(7, 7, 8, 8);

	minimap.pop();
}

function drawMinimap() {
	push();
	resetMatrix();
	resetCustomCamera();
	ortho(-width / 2, width / 2, -height / 2, height / 2, -1000, 1000);

	const xOffset = (width / 2) - minimapSize - 20;
	const yOffset = (-height / 2) + 20;
	image(minimap, xOffset, yOffset, minimapSize, minimapSize);

	noFill();
	stroke(255);
	strokeWeight(2);
	rectMode(CORNER);
	rect(xOffset, yOffset, minimapSize, minimapSize);

	pop();
}

function drawMomentumMeter() {
	push();
	resetMatrix();
	resetCustomCamera();
	ortho(-width / 2, width / 2, -height / 2, height / 2, -1000, 1000);

	const paddingFromEdge = 280;
	const barWidth = 30;
	const barHeight = 200;
	const barX = width / 2 - paddingFromEdge;
	const barY = -height / 2 + 20;

	noStroke();
	fill(50, 50, 50);
	rectMode(CORNER);
	rect(barX, barY, barWidth, barHeight);

	stroke(255);
	strokeWeight(2);
	noFill();
	rect(barX, barY, barWidth, barHeight);

    let momentumRatio;
    let fillColor;
    let fillHeight;

    if (isFlyingWithWings) {
        momentumRatio = 1.0;
        fillColor = color(0, 255, 255); 
        fillHeight = barHeight;
        currentFillHeight = fillHeight; 
    } else {
	    momentumRatio = constrain((momentum - 1.0) / (maxMomentum - 1.0), 0, 1);
	    fillHeight = momentumRatio * barHeight;

	    if (momentumRatio <= 0.33) {
		    fillColor = lerpColor(color(0, 255, 0), color(255, 255, 0), momentumRatio / 0.33);
	    } else if (momentumRatio <= 0.66) {
		    fillColor = lerpColor(color(255, 255, 0), color(255, 165, 0), (momentumRatio - 0.33) / 0.33);
	    } else {
		    fillColor = lerpColor(color(255, 165, 0), color(255, 0, 0), (momentumRatio - 0.66) / 0.34);
	    }
        currentFillHeight = lerp(currentFillHeight || 0, fillHeight, 0.1);
    }

	noStroke();
	fill(fillColor);
	rect(barX, barY + barHeight - currentFillHeight, barWidth, currentFillHeight);

	pop();
}

function drawSlowMotionMeter() {
	push();
	resetMatrix();
	resetCustomCamera();
	ortho(-width / 2, width / 2, -height / 2, height / 2, -1000, 1000);

	const paddingFromEdge = 320;
	const barWidth = 30;
	const barHeight = 200;
	const barX = width / 2 - paddingFromEdge;
	const barY = -height / 2 + 20;

	noStroke();
	fill(50, 50, 50);
	rectMode(CORNER);
	rect(barX, barY, barWidth, barHeight);

	stroke(255);
	strokeWeight(2);
	noFill();
	rect(barX, barY, barWidth, barHeight);

	let smRatio = constrain(slowMotionMeterValue, 0, 1);
	let fillHeight = smRatio * barHeight;

	let c1 = color(204, 249, 255);
	let c2 = color(124, 232, 255);
	let c3 = color(85, 208, 255);
	let c4 = color(0, 172, 223);
	let c5 = color(0, 128, 191);
	let finalFillColor;

	if (smRatio <= 0.25) {
		finalFillColor = lerpColor(c1, c2, map(smRatio, 0, 0.25, 0, 1));
	} else if (smRatio <= 0.5) {
		finalFillColor = lerpColor(c2, c3, map(smRatio, 0.25, 0.5, 0, 1));
	} else if (smRatio <= 0.75) {
		finalFillColor = lerpColor(c3, c4, map(smRatio, 0.5, 0.75, 0, 1));
	} else {
		finalFillColor = lerpColor(c4, c5, map(smRatio, 0.75, 1.0, 0, 1));
	}

	slowMotionCurrentFillHeight = lerp(slowMotionCurrentFillHeight || 0, fillHeight, 0.1);

	noStroke();
	fill(finalFillColor);
	rect(barX, barY + barHeight - slowMotionCurrentFillHeight, barWidth, slowMotionCurrentFillHeight);

	pop();
}

function drawHeart(x, y, size, fillColor) {
	push();
	translate(x, y);

	strokeJoin(ROUND);
	stroke(255);
	strokeWeight(1);
	fill(fillColor);

	beginShape();
	vertex(0, -0.40 * size);
	bezierVertex(
		-0.40 * size, -0.75 * size,
		-0.80 * size, -0.20 * size,
		0.00 * size, 0.40 * size
	);
	bezierVertex(
		0.80 * size, -0.30 * size,
		0.40 * size, -0.75 * size,
		0.00 * size, -0.40 * size
	);
	endShape(CLOSE);

	pop();
}

function drawLivesIndicator() {
	push();
	resetMatrix();
	resetCustomCamera();
	ortho(-width / 2, width / 2, -height / 2, height / 2, -1000, 1000);

	const heartCount = 10;
	const barHeight = 200;
	const heartSize = 20;

	const spacing = (barHeight - heartSize) / (heartCount - 0.7);
	const indicatorX = (width / 2) - 320 - 40;
	const startY = -height / 2 + 30;

	for (let i = 0; i < heartCount; i++) {
		let centerY = startY + (heartSize * 0.4) + i * spacing;
		let fillColor = (i < lives) ? color(255, 0, 0) : color(100);
		drawHeart(indicatorX, centerY, heartSize, fillColor);
	}

	pop();
}

