	rectMode(CENTER);

	for (let i = 0; i < numSlots; i++) {
		let slotX = barStartX + i * (slotSize + slotSpacing) + slotSize / 2;
		let item = prestigeItems[i];

		let currentImage = prestigeItemPlaceholderImage;
		if (item.id === 0 && prestigeItem1Image && prestigeItem1Image.width > 0) {
			currentImage = prestigeItem1Image;
		} else if (item.id === 1 && prestigeItem2Image && prestigeItem2Image.width > 0) {
            currentImage = prestigeItem2Image;
        } else if (item.id === 2 && prestigeItem3Image && prestigeItem3Image.width > 0) {
            currentImage = prestigeItem3Image;
        } else if (item.id === 3 && prestigeItem4Image && prestigeItem4Image.width > 0) {
            currentImage = prestigeItem4Image;
        } else if (item.id === 4 && prestigeItem5Image && prestigeItem5Image.width > 0) {
            currentImage = prestigeItem5Image;
        }

		fill(30, 30, 30, 200);
		stroke(80);
		strokeWeight(1);
		square(slotX, barY, slotSize, 4);

		if (currentImage && currentImage.width > 0) {
			 let imgSize = slotSize * 0.8;
			 image(currentImage, slotX, barY, imgSize, imgSize);
		}

		if (!item.purchased) {
			fill(0, 0, 0, 180);
			noStroke();
			square(slotX, barY, slotSize);
		} else {
			if (item.isActive) {
				noFill();
				stroke(0, 255, 0, 200);
				strokeWeight(3);
				square(slotX, barY, slotSize + 4);
			} else if (item.isOnCooldown) {
				fill(0, 0, 0, 180);
				noStroke();
				square(slotX, barY, slotSize);

				fill(50, 50, 50, 200);
				noStroke();
				let cooldownProgress = item.cooldownTimer / item.baseCooldown;
				let angle = TWO_PI * cooldownProgress;
				arc(slotX, barY, slotSize * 0.9, slotSize * 0.9, -HALF_PI, -HALF_PI + angle, PIE);

