// === Tab: Movement ===
function updateMovement(finalSpeed, dt) {
    playerMadeNoiseThisFrame = false;

    if (isConsoleVisible || playerDead || dt <= 0) {
        if(angelWingsSound && angelWingsSound.isLooping()) angelWingsSound.stop();
        isFlyingWithWings = false;
        targetFlyHeight = floorY;
        return;
    }

    let effectiveSpeedFactor = (timeScale > 0) ? timeScale : (timeScale < 0 ? 1.0 / Math.abs(timeScale) : 0);

    if (effectiveSpeedFactor === 0) {
         return;
    }

    currentFlyHeight = lerp(currentFlyHeight, targetFlyHeight, dt * angelWingsTransitionSpeed);

    let bobbingOffset = 0;
    if (isFlyingWithWings && abs(currentFlyHeight - (floorY - angelWingsFlyHeight)) < 5) {
        bobbingOffset = sin(millis() / 1000.0 * angelWingsBobFrequency) * angelWingsBobAmplitude;
    }

    let onGround = (abs(currentFlyHeight - floorY) < 1 && !isJumping && !isFlyingWithWings && abs(velocityY) < 0.1);

    let inputDir = createVector(0, 0, 0);

    if (noclip) {
        isFlyingWithWings = false;
        targetFlyHeight = floorY;
        if (angelWingsSound && angelWingsSound.isLooping()) { angelWingsSound.stop(); }
        let forwardDir = createVector(
            cos(player.angleY) * cos(player.angleX),
            sin(player.angleX),
            sin(player.angleY) * cos(player.angleX)
        );
        let rightDir = createVector(-sin(player.angleY), 0, cos(player.angleY));

        if (moveForward) inputDir.add(forwardDir);
        if (moveBackward) inputDir.sub(forwardDir);
        if (moveLeft) inputDir.sub(rightDir);
        if (moveRight) inputDir.add(rightDir);
        if (moveUp) inputDir.y += 1;
        if (moveDown) inputDir.y -= 1;

        if (inputDir.magSq() > 0) {
            inputDir.normalize().mult(finalSpeed);
            player.velocity.lerp(inputDir, 0.2);
        } else {
            player.velocity.mult(friction);
        }

        player.x += player.velocity.x * effectiveSpeedFactor * dt;
        player.y += player.velocity.y * effectiveSpeedFactor * dt; 
        player.z += player.velocity.z * effectiveSpeedFactor * dt;
        currentFlyHeight = player.y; 
        targetFlyHeight = player.y;

    } else if (isFlyingWithWings || abs(currentFlyHeight - floorY) > 1) { 
        player.y = currentFlyHeight + bobbingOffset; 
        velocityY = 0; 
        isJumping = false;

        let flySpeed = baseSpeed * angelWingsSpeedMultiplier;

        let forwardDir = createVector(cos(player.angleY), 0, sin(player.angleY));
        let rightDir = createVector(-sin(player.angleY), 0, cos(player.angleY));

        if (moveForward) inputDir.add(forwardDir);
        if (moveBackward) inputDir.sub(forwardDir);
        if (moveLeft) inputDir.sub(rightDir);
        if (moveRight) inputDir.add(rightDir);

        let targetVelX = 0;
        let targetVelZ = 0;

        if (inputDir.magSq() > 0) {
            inputDir.normalize().mult(flySpeed);
            targetVelX = inputDir.x;
            targetVelZ = inputDir.z;
        }

        let baseLerpFactor = 0.15;
        let lerpFactor = 1.0 - pow(1.0 - baseLerpFactor, dt * 60);
        lerpFactor = constrain(lerpFactor, 0, 1);

        player.velocity.x = lerp(player.velocity.x, targetVelX, lerpFactor);
        player.velocity.z = lerp(player.velocity.z, targetVelZ, lerpFactor);

        let deltaX = player.velocity.x * effectiveSpeedFactor * dt;
        let deltaZ = player.velocity.z * effectiveSpeedFactor * dt;

        let newX = player.x + deltaX;
        let newZ = player.z + deltaZ;

        if (!checkCollision(newX, player.z)) {
            player.x = newX;
        }

        if (!checkCollision(player.x, newZ)) {
            player.z = newZ;
        }

         if (walkingSound.isPlaying() && walkingSound.getVolume() > 0) { fadeOutSound(walkingSound); }
         if (runningSound.isPlaying() && runningSound.getVolume() > 0) { fadeOutSound(runningSound); }
         if (walkStopTimeoutId) { clearTimeout(walkStopTimeoutId); walkStopTimeoutId = null; }
         if (runStopTimeoutId) { clearTimeout(runStopTimeoutId); runStopTimeoutId = null; }

    } else { 

        let forwardDir = createVector(cos(player.angleY), 0, sin(player.angleY));
        let rightDir = createVector(-sin(player.angleY), 0, cos(player.angleY));

        if (moveForward) inputDir.add(forwardDir);
        if (moveBackward) inputDir.sub(forwardDir);
        if (moveLeft) inputDir.sub(rightDir);
        if (moveRight) inputDir.add(rightDir);

        if (!onGround) {
             let airControlFactor = 0.2;
             let airInputDir = createVector(0,0,0);
             if (moveForward) airInputDir.add(forwardDir.copy().mult(airControlFactor));
             if (moveBackward) airInputDir.sub(forwardDir.copy().mult(airControlFactor));
             if (moveLeft) airInputDir.sub(rightDir.copy().mult(airControlFactor));
             if (moveRight) airInputDir.add(rightDir.copy().mult(airControlFactor));
             inputDir.add(airInputDir);
        }

        let targetVelX = 0;
        let targetVelZ = 0;

        if (inputDir.magSq() > 0) {
            let speedToUse = finalSpeed;

            inputDir.normalize().mult(speedToUse);
            targetVelX = inputDir.x;
            targetVelZ = inputDir.z;

            let baseLerpFactor = 0.2;
            let lerpFactor = 1.0 - pow(1.0 - baseLerpFactor, dt * 60);
            lerpFactor = constrain(lerpFactor, 0, 1);

            player.velocity.x = lerp(player.velocity.x, targetVelX, lerpFactor);
            player.velocity.z = lerp(player.velocity.z, targetVelZ, lerpFactor);

        } else {
            let baseFriction = friction;
            let frictionFactor = pow(baseFriction, dt * 60);
            frictionFactor = constrain(frictionFactor, 0, 1);

            player.velocity.x *= frictionFactor;
            player.velocity.z *= frictionFactor;
        }

        let deltaX = player.velocity.x * effectiveSpeedFactor * dt;
        let deltaZ = player.velocity.z * effectiveSpeedFactor * dt;

        let newX = player.x + deltaX;
        let newZ = player.z + deltaZ;

        if (!checkCollision(newX, player.z)) {
            player.x = newX;
        } else {
            player.velocity.x = 0;
            if (abs(targetVelX) > 0.01) resetMomentum();
        }

        if (!checkCollision(player.x, newZ)) {
            player.z = newZ;
        } else {
            player.velocity.z = 0;
             if (abs(targetVelZ) > 0.01) resetMomentum();
        }

        if (!isFlyingWithWings && abs(currentFlyHeight - floorY) <= 1) {
            if (!onGround || isJumping) {
                velocityY += gravity * effectiveSpeedFactor * dt;
                player.y += velocityY * effectiveSpeedFactor * dt;

                const maxJumpHeight = 100;
                let ceilingY = floorY - maxJumpHeight;
                if (player.y < ceilingY) { player.y = ceilingY; velocityY = 0; }

                if (player.y >= floorY) {
                    player.y = floorY;
                    currentFlyHeight = floorY; 
                    targetFlyHeight = floorY;
                    isJumping = false;
                    velocityY = 0;
                    let randomLand = floor(random(3));
                    if (randomLand === 0) landingSound1.play(0, 1, fxVolume);
                    else if (randomLand === 1) landingSound2.play(0, 1, fxVolume);
                    else landingSound3.play(0, 1, fxVolume);
                    if (momentum > 1.0 && !spacePressed) {
                         momentum = max(momentum - 0.05, 1.0);
                         currentSpeed = baseSpeed * momentum;
                    }
                }
            } else { 
                 player.y = floorY;
                 currentFlyHeight = floorY;
                 targetFlyHeight = floorY;
                 velocityY = 0;
            }

            if (spacePressed && onGround && !isJumping) {
                isJumping = true;
                velocityY = -jumpStrength;
                playerMadeNoiseThisFrame = true;
                if (player.velocity.magSq() > 0.1 || momentum > 1.0) {
                     momentum = min(momentum + momentumGainRate, maxMomentum);
                     currentSpeed = baseSpeed * momentum;
                } else { resetMomentum(); }
            }
        } else {

             player.y = currentFlyHeight;
        }
    } 

    let isMovingHorizontally = !noclip && !isFlyingWithWings && (abs(player.velocity.x) > 0.1 || abs(player.velocity.z) > 0.1);

    if (isMovingHorizontally && onGround) {
        if (running) {
            if (!runningSound.isPlaying() || runningSound.getVolume() === 0) { fadeInSound(runningSound); }
            if (walkingSound.isPlaying() && walkingSound.getVolume() > 0) { fadeOutSound(walkingSound); }
            if (walkStopTimeoutId) { clearTimeout(walkStopTimeoutId); walkStopTimeoutId = null; }
            if (runStopTimeoutId) { clearTimeout(runStopTimeoutId); runStopTimeoutId = null; }
            playerMadeNoiseThisFrame = true;
        } else {
            if (!walkingSound.isPlaying() || walkingSound.getVolume() === 0) { fadeInSound(walkingSound); }
            if (runningSound.isPlaying() && runningSound.getVolume() > 0) { fadeOutSound(runningSound); }
            if (walkStopTimeoutId) { clearTimeout(walkStopTimeoutId); walkStopTimeoutId = null; }
            if (runStopTimeoutId) { clearTimeout(runStopTimeoutId); runStopTimeoutId = null; }
        }
        lastMoveTime = millis();
    } else if (onGround || (!isFlyingWithWings && abs(currentFlyHeight - floorY) <=1 ) ) { 
        if (walkingSound.isPlaying() && walkingSound.getVolume() > 0) { fadeOutSound(walkingSound); }
        if (runningSound.isPlaying() && runningSound.getVolume() > 0) { fadeOutSound(runningSound); }
        if (!isMovingHorizontally && onGround) {
            if (walkingSound.isPlaying() && !walkStopTimeoutId) {
                 walkStopTimeoutId = setTimeout(() => { if (walkingSound) walkingSound.stop(); walkStopTimeoutId = null; }, 150);
            }
            if (runningSound.isPlaying() && !runStopTimeoutId) {
                 runStopTimeoutId = setTimeout(() => { if (runningSound) runningSound.stop(); runStopTimeoutId = null; }, 150);
            }
        } else {
            if (walkStopTimeoutId) { clearTimeout(walkStopTimeoutId); walkStopTimeoutId = null; }
            if (runStopTimeoutId) { clearTimeout(runStopTimeoutId); runStopTimeoutId = null; }
        }
    }

    if (player.y > floorY && !isFlyingWithWings && targetFlyHeight === floorY) {
        player.y = floorY;
        currentFlyHeight = floorY;
        if (velocityY > 0) velocityY = 0; 
    }
}

function fadeOutSound(sound) {
    if (sound && sound.isPlaying()) {

        sound.setVolume(0, 0.1);
    }
}

function fadeInSound(sound) {
    if (!sound) return; 

    sound.stop();

    if (sound === walkingSound && walkStopTimeoutId) {
        clearTimeout(walkStopTimeoutId);
        walkStopTimeoutId = null;
    } else if (sound === runningSound && runStopTimeoutId) {
        clearTimeout(runStopTimeoutId);
        runStopTimeoutId = null;
    }

    sound.setVolume(0); 
    sound.loop();

    sound.setVolume(fxVolume, 0.1);
}

function resetMomentum() {
    momentum = 1.0; 
    currentSpeed = baseSpeed; 
    bunnyhopTime = 0; 
}

function checkCollision(testX, testZ) {
    if (wallPassActive) {
        return false;
    }

    const cellX = floor(testX / cellSize);
    const cellZ = floor(testZ / cellSize);

    for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
            const neighborCellX = cellX + i;
            const neighborCellZ = cellZ + j;

            const neighborChunkX = floor(neighborCellX / chunkSize);
            const neighborChunkZ = floor(neighborCellZ / chunkSize);
            const neighborChunkKey = neighborChunkX + "," + neighborChunkZ;

            const neighborChunk = mazeChunks[neighborChunkKey];

            if (neighborChunk) {
                let localX = neighborCellX % chunkSize;
                let localZ = neighborCellZ % chunkSize;

                if (localX < 0) localX += chunkSize;
                if (localZ < 0) localZ += chunkSize;

                if (localX >= 0 && localX < chunkSize && localZ >= 0 && localZ < chunkSize) {
                    if (neighborChunk.maze[localX][localZ] === 1) {

                        const wallCenterX = (neighborCellX + 0.5) * cellSize;
                        const wallCenterZ = (neighborCellZ + 0.5) * cellSize;

                        const dx = testX - wallCenterX;
                        const dz = testZ - wallCenterZ;

                        const distanceX = abs(dx) - (cellSize / 2 + playerRadius);
                        const distanceZ = abs(dz) - (cellSize / 2 + playerRadius);

                        if (distanceX < 0 && distanceZ < 0) {
                            return true;
                        }
                    }
                }
            }
        }
    }

    return false;
}

function checkCollisionForEnemy(testX, testZ) {
    const cellX = floor(testX / cellSize); 
    const cellZ = floor(testZ / cellSize); 

    for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
            const neighborCellX = cellX + i; 
            const neighborCellZ = cellZ + j; 

            const neighborChunkX = floor(neighborCellX / chunkSize); 
            const neighborChunkZ = floor(neighborCellZ / chunkSize); 
            const neighborChunkKey = neighborChunkX + "," + neighborChunkZ; 

            const neighborChunk = mazeChunks[neighborChunkKey]; 

            if (neighborChunk) {
                let localX = neighborCellX % chunkSize; 
                let localZ = neighborCellZ % chunkSize; 

                if (localX < 0) localX += chunkSize; 
                if (localZ < 0) localZ += chunkSize; 

                if (localX >= 0 && localX < chunkSize && localZ >= 0 && localZ < chunkSize) {
                    if (neighborChunk.maze[localX][localZ] === 1) {

                        const wallCenterX = (neighborCellX + 0.5) * cellSize;
                        const wallCenterZ = (neighborCellZ + 0.5) * cellSize;

                        const dx = testX - wallCenterX; 
                        const dz = testZ - wallCenterZ; 

                        const distanceX = abs(dx) - (cellSize / 2 + playerRadius);
                        const distanceZ = abs(dz) - (cellSize / 2 + playerRadius);

                        if (distanceX < 0 && distanceZ < 0) {
                            return true; 
                        }
                    }
                }
            }
        }
    }
    return false; 
}

function teleportEnemyToNearestOpenCellFarFrom(targetX, targetZ) {
    let minDistanceSq = Infinity;
    let bestCellX = -1;
    let bestCellZ = -1;
    let foundCell = false;

    const searchChunkRadius = 2;
    const targetChunkX = floor(targetX / (cellSize * chunkSize));
    const targetChunkZ = floor(targetZ / (cellSize * chunkSize));

    for (let chX = targetChunkX - searchChunkRadius; chX <= targetChunkX + searchChunkRadius; chX++) {
        for (let chZ = targetChunkZ - searchChunkRadius; chZ <= targetChunkZ + searchChunkRadius; chZ++) {
            const key = chX + "," + chZ;
            const chunk = mazeChunks[key];
            if (!chunk) continue;

            const baseX = chX * chunkSize * cellSize;
            const baseZ = chZ * chunkSize * cellSize;

            for (let i = 0; i < chunkSize; i++) {
                for (let j = 0; j < chunkSize; j++) {
                    if (chunk.maze[i][j] === 0) {
                        let potentialX = baseX + (i + 0.5) * cellSize;
                        let potentialZ = baseZ + (j + 0.5) * cellSize;
                        let distSq = (potentialX - targetX) ** 2 + (potentialZ - targetZ) ** 2;

                        if (distSq < minDistanceSq) {
                            if (!checkCollisionForEnemy(potentialX, potentialZ)) {
                                 minDistanceSq = distSq;
                                 bestCellX = potentialX;
                                 bestCellZ = potentialZ;
                                 foundCell = true;
                            }
                        }
                    }
                }
            }
        }
    }

    if (foundCell) {
        enemy = {
            x: bestCellX,
            y: floorY,
            z: bestCellZ,
            angleY: 0,
            lastPosition: createVector(bestCellX, floorY, bestCellZ),
            stuckTimer: 0,
            aiState: 'searching',
            isDissolving: false,
            dissolveProgress: 0.0
        };
         enemyPath = [];
         enemyLastTargetCell = { x: -1, z: -1 };
         enemyAISearchTarget = null;
         enemyChaseTimer = 0;
         enemyLastKnownPlayerPos = null;
         enemyIsAwareOfPlayer = false;
    } else {
        console.error("CRITICAL SPAWN ERROR: Could not find any open cell for fallback spawn!");
        enemy = null;
    }
}

function teleportEnemyNearPlayer(enemyToTeleport, targetPlayer, minDist, maxDist){
  let foundSpot=false;
  let attempts=60;
  let spotX, spotZ;

  while(attempts-- && !foundSpot){
    const angle  = random(TWO_PI);
    const dist   = random(minDist,maxDist);
    spotX  = targetPlayer.x + cos(angle)*dist;
    spotZ  = targetPlayer.z + sin(angle)*dist;

    const forward        = createVector(cos(targetPlayer.angleY),sin(targetPlayer.angleY));
    const dirToSpotNorm  = createVector(spotX-targetPlayer.x,spotZ-targetPlayer.z).normalize();
    const dotForwardSpot = forward.dot(dirToSpotNorm);

    if(dotForwardSpot > -0.2) continue;
    const cellX = floor(spotX/cellSize);
    const cellZ = floor(spotZ/cellSize);
    if(!isCellOpen(cellX,cellZ))        continue;
    if(checkCollisionForEnemy(spotX,spotZ)) continue;

    enemyToTeleport.x = spotX;
    enemyToTeleport.z = spotZ;
    enemyToTeleport.y = floorY;
    foundSpot = true;
  }

  if(foundSpot) {
      enemyToTeleport.isDissolving = false;
      enemyToTeleport.dissolveProgress = 0.0;
      enemyToTeleport.aiState = 'searching';
      if (!enemyToTeleport.lastPosition) {
         enemyToTeleport.lastPosition = createVector(spotX, floorY, spotZ);
      } else {
         enemyToTeleport.lastPosition.set(spotX, floorY, spotZ);
      }
      enemyToTeleport.stuckTimer = 0;
      enemyPath = [];
      enemyLastTargetCell = { x: -1, z: -1 };
      enemyAISearchTarget = null;
      enemyChaseTimer = 0;
      enemyLastKnownPlayerPos = null;
      enemyIsAwareOfPlayer = false;
      playerWasFarInHardMode = true;
  } else {
      teleportEnemyToNearestOpenCellFarFrom(player.x, player.z);
  }
}

function hasLineOfSight(x1, z1, x2, z2) {
    let dx = x2 - x1;
    let dz = z2 - z1;
    let distance = Math.sqrt(dx * dx + dz * dz);
    let stepSize = cellSize / 4; 
    let numSteps = Math.floor(distance / stepSize);

    if (numSteps <= 1) { 
        return !checkCollisionForEnemy((x1 + x2) / 2, (z1 + z2) / 2);
    }

    for (let i = 1; i < numSteps; i++) { 
        let t = i / numSteps;
        let currentX = x1 + t * dx;
        let currentZ = z1 + t * dz;

        let cellX = floor(currentX / cellSize);
        let cellZ = floor(currentZ / cellSize);

        let chunkX = floor(cellX / chunkSize);
        let chunkZ = floor(cellZ / chunkSize);
        let key = chunkX + "," + chunkZ;
        let chunk = mazeChunks[key];

        if (chunk) {
            let localX = cellX % chunkSize;
            if (localX < 0) localX += chunkSize;
            let localZ = cellZ % chunkSize;
            if (localZ < 0) localZ += chunkSize;

            if (localX >= 0 && localX < chunkSize && localZ >= 0 && localZ < chunkSize) {
                if (chunk.maze[localX][localZ] === 1) {
                    return false; 
                }
            } else {

                return false;
            }
        } else {

            return false;
        }
    }
    return true; 
}

function updateEnemy(dt) {
    if (!enemy || playerDead || noclip || showMainMenu || dt <= 0) return;

    if (enemy.isDissolving) {
        let currentDissolveRate = enemyDissolveRate;
        if (bothDissolvingDueToAngel) {
             currentDissolveRate = ANGEL_DISSOLVE_RATE;
        } else if (isEnergyShieldActive) {
            currentDissolveRate = enemyDissolveRate;
        }

        let effectiveDissolveRate = currentDissolveRate;
         if (timeScale !== 0) {
             effectiveDissolveRate *= (timeScale > 0 ? timeScale : (1.0 / Math.abs(timeScale)));
         } else {
             effectiveDissolveRate = 0;
         }

        enemy.dissolveProgress += effectiveDissolveRate * dt;
        enemy.dissolveProgress = min(enemy.dissolveProgress, 1.0);

        if (enemy.dissolveProgress >= 1.0) {
            despawnEnemy();
            if (bothDissolvingDueToAngel) {

            } else if (isEnergyShieldActive) {
                enemyRespawnScheduledAfterShield = true;
                enemyRespawnTimer = 10.0;
                initialEnemySpawnScheduled = false;
            }
            return;
        } else {
            return;
        }
    }
    if (enemy.aiState === 'idle_dissolving') {
        enemy.aiState = 'searching';
    }

    let effectiveSpeedFactor = timeScale > 0
        ? timeScale
        : (timeScale < 0 ? 1 / Math.abs(timeScale) : 0);
    if (effectiveSpeedFactor === 0) return;

    if (enemyLaughCooldownTimer > 0) {
        enemyLaughCooldownTimer -= dt;
    }

    if (enemyPathRecalculationTimer > 0) {
        enemyPathRecalculationTimer -= dt;
    }

    if (enemyLOSTimer > 0) {
        enemyLOSTimer -= dt;
    }

    let distToPlayerSq = (player.x - enemy.x)**2 + (player.z - enemy.z)**2;
    let playerInView = false;
    let directTargetX = player.x;
    let directTargetZ = player.z;
    let targetX, targetZ;
    let isFollowingPath = false;
    let heardNoise = false;
    let justBecameAware = false;
    let previousAwareness = enemyIsAwareOfPlayer;

    let difficultySpeedMultiplier = 1.0;
    let difficultyRageMultiplier = 1.0;

    switch(selectedDifficulty) {
        case DIFFICULTY_EASY:
            difficultySpeedMultiplier = 0.8;
            difficultyRageMultiplier = 0.8;
            break;
        case DIFFICULTY_MEDIUM:
            difficultySpeedMultiplier = 1.0;
            difficultyRageMultiplier = 1.0;
            break;
        case DIFFICULTY_HARD:
            difficultySpeedMultiplier = 1.2;
            difficultyRageMultiplier = 1.2;
            break;
    }

    let currentReaperRageEffect = 1.0 + (reaperRage - 1.0) * difficultyRageMultiplier;
    let finalEnemySpeed = baseEnemySpeed * difficultySpeedMultiplier * currentReaperRageEffect;

     if (selectedDifficulty !== DIFFICULTY_HARD) {
        if (playerMadeNoiseThisFrame && distToPlayerSq < ENEMY_NOISE_RADIUS * ENEMY_NOISE_RADIUS) {
            heardNoise = true;
            if (enemy.aiState !== 'chasing') {
                justBecameAware = true;
            }
            enemy.aiState = 'chasing';
            enemyChaseTimer = 0;
            enemyLastKnownPlayerPos = null;
            enemyPath = [];
            enemyLastTargetCell = { x: -1, z: -1 };
            enemyPathRecalculationTimer = 0;
            enemyLOSTimer = 0; 
        }
    }

    if (!heardNoise && selectedDifficulty !== DIFFICULTY_HARD) {
        if (distToPlayerSq < ENEMY_VIEW_DISTANCE * ENEMY_VIEW_DISTANCE) {
            let vectorToPlayer = createVector(player.x - enemy.x, 0, player.z - enemy.z);
            let angleToPlayer = atan2(vectorToPlayer.z, vectorToPlayer.x);
            let angleDifference = abs(angleToPlayer - enemy.angleY);
            if (angleDifference > PI) angleDifference = TWO_PI - angleDifference;

            if (angleDifference <= ENEMY_FOV_ANGLE / 2) {

                 if (enemyLOSTimer <= 0) {
                     if (hasLineOfSight(enemy.x, enemy.z, player.x, player.z)) {
                        playerInView = true;
                     }

                     enemyLOSTimer = ENEMY_LOS_CHECK_INTERVAL;
                 }
            }
        } else {

             if(enemyLOSTimer < 0.1) enemyLOSTimer = ENEMY_LOS_CHECK_INTERVAL * 0.5; 
        }
    }

    let playLaughThisFrame = false;

    if (selectedDifficulty === DIFFICULTY_HARD) {
        enemy.aiState = 'chasing';
        targetX = directTargetX;
        targetZ = directTargetZ;
        enemyChaseTimer = 0;
        enemyLastKnownPlayerPos = null;
        enemyIsAwareOfPlayer = true;
        if (enemyPath.length > 0) {
             enemyPath = [];
             enemyLastTargetCell = { x: -1, z: -1 };
        }

        if (distToPlayerSq > ENEMY_LAUGH_HARD_FAR_DIST_SQ) {
             playerWasFarInHardMode = true;
        } else if (playerWasFarInHardMode && distToPlayerSq < ENEMY_LAUGH_HARD_CLOSE_DIST_SQ) {
             if (enemyLaughCooldownTimer <= 0) {
                 playLaughThisFrame = true;
                 playerWasFarInHardMode = false;
             }
        }

    } else if (heardNoise) {
        targetX = directTargetX;
        targetZ = directTargetZ;
        enemyIsAwareOfPlayer = true;
        if (enemyPath.length > 0) {
             enemyPath = [];
             enemyLastTargetCell = { x: -1, z: -1 };
        }
        if (justBecameAware && !previousAwareness && enemyLaughCooldownTimer <= 0) {
             playLaughThisFrame = true;
        }
    } else if (playerInView) {
         if (enemy.aiState !== 'chasing') {
            justBecameAware = true;
            enemyLOSTimer = 0; 
         }
         enemy.aiState = 'chasing';
         enemyChaseTimer = 0;
         enemyLastKnownPlayerPos = null;
         enemyAISearchTarget = null;
         enemyAISearchTimer = 0;
         targetX = directTargetX;
         targetZ = directTargetZ;
         enemyIsAwareOfPlayer = true;
         if (enemyPath.length > 0) {
              enemyPath = [];
              enemyLastTargetCell = { x: -1, z: -1 };
         }
         if (justBecameAware && !previousAwareness && enemyLaughCooldownTimer <= 0) {
             playLaughThisFrame = true;
         }
    } else {

        if (enemy.aiState === 'chasing') {

             if (enemyChaseTimer <= 0 && !enemyLastKnownPlayerPos) {
                 enemyLastKnownPlayerPos = { x: player.x, z: player.z };
                 enemyChaseTimer = ENEMY_LOS_GRACE_PERIOD;
                 enemyPathRecalculationTimer = 0;
                 enemyLOSTimer = 0; 
             }

             if (enemyChaseTimer > 0) {
                enemyChaseTimer -= dt;
                if (enemyLastKnownPlayerPos) {
                     targetX = enemyLastKnownPlayerPos.x;
                     targetZ = enemyLastKnownPlayerPos.z;
                } else {
                     enemy.aiState = 'searching';
                     enemyChaseTimer = 0;
                     enemyIsAwareOfPlayer = false;
                     enemyPath = [];
                     enemyLastTargetCell = { x: -1, z: -1 };
                }
             } else {

                enemy.aiState = 'searching';
                enemyLastKnownPlayerPos = null;
                enemyIsAwareOfPlayer = false;
                enemyPath = [];
                enemyLastTargetCell = { x: -1, z: -1 };
                enemyLOSTimer = 0; 
             }
        }

        if (enemy.aiState === 'searching') {
             enemyIsAwareOfPlayer = false;
             enemyPath = [];
             enemyLastTargetCell = { x: -1, z: -1 };

             if (!enemyAISearchTarget || (enemy.x === enemyAISearchTarget.x && enemy.z === enemyAISearchTarget.z) || enemyAISearchTimer <= 0) {

                 let attempts = 10;
                 let foundNewTarget = false;
                 while(attempts-- > 0 && !foundNewTarget) {
                     let angle = random(TWO_PI);
                     let dist = random(enemyAISearchRadius * 0.5, enemyAISearchRadius);
                     let potentialTargetX = enemy.x + cos(angle) * dist;
                     let potentialTargetZ = enemy.z + sin(angle) * dist;
                     let cellX = floor(potentialTargetX / cellSize);
                     let cellZ = floor(potentialTargetZ / cellSize);

                     if (isCellOpen(cellX, cellZ)) {
                         enemyAISearchTarget = { x: (cellX + 0.5) * cellSize, z: (cellZ + 0.5) * cellSize };
                         enemyAISearchTimer = enemyAISearchDuration;
                         foundNewTarget = true;
                     }
                 }
                 if (!foundNewTarget) {
                     enemyAISearchTarget = { x: enemy.x, z: enemy.z };
                     enemyAISearchTimer = 1000;
                 }
             }
             if (enemyAISearchTarget) {
                 targetX = enemyAISearchTarget.x;
                 targetZ = enemyAISearchTarget.z;
                 enemyAISearchTimer -= dt * 1000;
             } else {

                 targetX = enemy.x;
                 targetZ = enemy.z;
             }
        }
    }

    if (playLaughThisFrame && enemyLaughSounds.length > 0) {
        let laughIndex;
        do {
            laughIndex = floor(random(enemyLaughSounds.length));
        } while (enemyLaughSounds.length > 1 && laughIndex === lastLaughIndex);
        lastLaughIndex = laughIndex;

        let currentDist = sqrt(distToPlayerSq);
        let distFactor = constrain(1.0 - (currentDist / ENEMY_LAUGH_MAX_DIST), 0.0, 1.0);
        let volume = fxVolume * map(distFactor, 0.0, 1.0, ENEMY_LAUGH_MIN_VOLUME_FACTOR, 1.0);
        volume = max(volume, fxVolume * ENEMY_LAUGH_MIN_VOLUME_FACTOR);

        enemyLaughSounds[laughIndex].play(0, 1, volume);
        enemyLaughCooldownTimer = ENEMY_LAUGH_COOLDOWN_DURATION;
    }

    let needsPathfinding = (enemy.aiState === 'chasing' && (selectedDifficulty === DIFFICULTY_HARD || !playerInView));

    if (needsPathfinding) {
        let targetCellX = floor(targetX / cellSize);
        let targetCellZ = floor(targetZ / cellSize);
        let enemyCellX = floor(enemy.x / cellSize);
        let enemyCellZ = floor(enemy.z / cellSize);

        let needsNewPathCheck = false;

        if (targetCellX !== enemyLastTargetCell.x || targetCellZ !== enemyLastTargetCell.z) {
            needsNewPathCheck = true;
        }
        else if (enemyPath.length < 2 && dist(enemy.x, enemy.z, targetX, targetZ) > cellSize * 1.5) {
             needsNewPathCheck = true;
        }
        else if (enemyPathRecalculationTimer <= 0) {
            needsNewPathCheck = true;
        }

        if (needsNewPathCheck && enemyPathRecalculationTimer <= 0) {
            if (enemyCellX !== targetCellX || enemyCellZ !== targetCellZ) {
                const newPath = findPath(enemyCellX, enemyCellZ, targetCellX, targetCellZ);
                if (newPath && newPath.length > 1) {
                    enemyPath = newPath;
                } else {
                    enemyPath = [];
                }
            } else {
                enemyPath = [];
            }
            enemyLastTargetCell.x = targetCellX;
            enemyLastTargetCell.z = targetCellZ;
            enemyPathRecalculationTimer = ENEMY_PATH_RECALCULATION_INTERVAL;
        }

        if (enemyPath.length > 1) {
            const nextNode = enemyPath[1];
            targetX = (nextNode.x + 0.5) * cellSize;
            targetZ = (nextNode.z + 0.5) * cellSize;
            isFollowingPath = true;
        } else {
             isFollowingPath = false;
        }
    } else {
        isFollowingPath = false;
        enemyPath = [];
        enemyLastTargetCell = { x: -1, z: -1 };
    }

    const stuckCheckInterval = 0.5;
    enemy.stuckTimer += dt;

    if (enemy.stuckTimer >= stuckCheckInterval) {
        let currentEnemyPos = createVector(enemy.x, enemy.y, enemy.z);
        if (enemy.lastPosition) {
             let distMovedSq = (currentEnemyPos.x - enemy.lastPosition.x)**2 + (currentEnemyPos.z - enemy.lastPosition.z)**2;
             const stuckThresholdDistanceSq = (finalEnemySpeed * enemyStepSize * stuckCheckInterval * 0.1) ** 2;
             const stuckTimeToAttemptRecalc = 1.5;

             if (distMovedSq < stuckThresholdDistanceSq) {
                 if (enemy.stuckTimer >= stuckTimeToAttemptRecalc) {
                     enemyPath = [];
                     enemyLastTargetCell.x = -1;
                     enemyPathRecalculationTimer = 0;
                     enemy.stuckTimer = 0;
                     enemyAISearchTarget = null;
                     enemyLOSTimer = 0; 
                 }
             } else {
                 enemy.lastPosition.set(enemy.x, enemy.y, enemy.z);
                 enemy.stuckTimer = 0;
             }
        } else {
             enemy.lastPosition = createVector(enemy.x, enemy.y, enemy.z);
             enemy.stuckTimer = 0;
        }
    }

     const maxDistSq = maxEnemyDistanceThreshold * maxEnemyDistanceThreshold;
     if (distToPlayerSq > maxDistSq) {
         teleportEnemyNearPlayer(enemy, player, minTeleportDistance, maxTeleportDistance);
         return;
     }

     let dir = createVector(targetX - enemy.x, 0, targetZ - enemy.z);
    let distanceToTarget = dir.mag();
    let moved = false;
    let arrivalThreshold = isFollowingPath ? cellSize * 0.4 : playerRadius * 0.5;

    if (distanceToTarget > arrivalThreshold) {
        dir.normalize();
        let displacementMagnitude = finalEnemySpeed * enemyStepSize * effectiveSpeedFactor * dt;

        if (displacementMagnitude > distanceToTarget) {
            displacementMagnitude = distanceToTarget;
        }

        let moveX = dir.x * displacementMagnitude;
        let moveZ = dir.z * displacementMagnitude;
        let nextX = enemy.x + moveX;
        let nextZ = enemy.z + moveZ;

        let originalX = enemy.x;

        let movedX = false;
        let movedZ = false;

        if (!checkCollisionForEnemy(nextX, enemy.z)) {
            enemy.x = nextX;
            movedX = true;
        }
        if (!checkCollisionForEnemy(enemy.x, nextZ)) {
            enemy.z = nextZ;
            movedZ = true;
        }

        moved = movedX || movedZ;
    }

      if (isFollowingPath && enemyPath.length > 1) {
        let nextNodeTargetX = (enemyPath[1].x + 0.5) * cellSize;
        let nextNodeTargetZ = (enemyPath[1].z + 0.5) * cellSize;
        let distToNextNodeSq = (nextNodeTargetX - enemy.x)**2 + (nextNodeTargetZ - enemy.z)**2;

        let nodeReachedThresholdSq = (cellSize * 0.6) ** 2;

        if (distToNextNodeSq < nodeReachedThresholdSq) {
            enemyPath.shift();
            enemyPathRecalculationTimer = 0;
            enemyLOSTimer = 0; 
        }
    }

     let currentDistToPlayerSq = (player.x - enemy.x)**2 + (player.z - enemy.z)**2;
     let catchRadius = playerRadius * 1.5;
     let catchRadiusSq = catchRadius * catchRadius;

     if (currentDistToPlayerSq < catchRadiusSq) {
         if (isEnergyShieldActive) {
             if (!enemy.isDissolving) {
                 enemy.isDissolving = true;
                 enemy.dissolveProgress = 0.0;
                 if (iWillBeBackSound) {
                     iWillBeBackSound.play(0, 1, fxVolume);
                 }
             }
             return;

         } else {
             if (lives <= 1) {
				if (loseSound && !playerDead) loseSound.play(0, 1, fxVolume);
                 playerDead = true; showDeathPopup = true; document.exitPointerLock();
                 despawnEnemy();
                 walkingSound.stop();
                 runningSound.stop();
                 if (angelWingsSound && angelWingsSound.isLooping()) {
                     angelWingsSound.stop();
                 }
                 isFlyingWithWings = false;
                 return;
             } else {
                 lives--;
                 despawnEnemy();
                 initialEnemySpawnScheduled = true;
                 enemyRespawnScheduledAfterShield = false;
                 enemySpawnStartTime = millis();
                 return;
             }
         }
     }

     enemy.y = floorY;
     let lookDx, lookDz;
     if (enemy.aiState === 'chasing' || playerInView || heardNoise) {
        lookDx = player.x - enemy.x;
        lookDz = player.z - enemy.z;
     } else {
        lookDx = targetX - enemy.x;
        lookDz = targetZ - enemy.z;
     }
     if (abs(lookDx) > 0.1 || abs(lookDz) > 0.1) {
        enemy.angleY = atan2(lookDz, lookDx);
     }
}

function updateCoins(dt) {
    if (isConsoleVisible || !focused || showDeathPopup || playerDead || dt <= 0) {
        return;
    }

    let effectiveSpeedFactor = timeScale > 0
        ? timeScale
        : (timeScale < 0 ? 1 / Math.abs(timeScale) : 0);
    if (effectiveSpeedFactor === 0) return;

    const rotationSpeed = 1.2;
    const baseMagnetSpeed = 120;
    const magnetSpeedMultiplier = 1.5;

    for (let i = coins.length - 1; i >= 0; i--) {
        let coin = coins[i];

        coin.angle += rotationSpeed * effectiveSpeedFactor * dt;
        coin.angle %= TWO_PI;

        let dx = player.x - coin.x;
        let dz = player.z - coin.z;
        let distanceSq = dx * dx + dz * dz;
        let distance = sqrt(distanceSq);

        if (coinMagnetLevel > 0) {
            let magnetRange = map(coinMagnetLevel, 0, 10, 0, 1000);
            let magnetRangeSq = magnetRange * magnetRange;

            if (distanceSq <= magnetRangeSq && distance > 1) {
                let dir = createVector(dx, 0, dz).normalize();

                let magnetSpeed = baseMagnetSpeed * pow(magnetSpeedMultiplier, coinMagnetLevel -1);
                let moveDist = magnetSpeed * effectiveSpeedFactor * dt;

                if (moveDist > distance) {
                     moveDist = distance;
                }

                coin.x += dir.x * moveDist;
                coin.z += dir.z * moveDist;

                dx = player.x - coin.x;
                dz = player.z - coin.z;
                distance = sqrt(dx * dx + dz * dz);
            }
        }

        let collectRadius = playerRadius * 1.5;
        if (distance < collectRadius) {
            let collectedCellX = floor(coin.x / cellSize);
            let collectedCellZ = floor(coin.z / cellSize);
            let cellKey = `${collectedCellX},${collectedCellZ}`;
            cellCooldownTimestamps.set(cellKey, millis());

            coins.splice(i, 1);

            coinsCollectedThisRound++;
            totalCoinsAllTime++;
            if(collectCoinSound) collectCoinSound.play(0, 1, fxVolume);
        }
    }

    if (!coinSpawnEnabled) return;

    let spawnIntervalFrames = floor(120 / coinSpawnRate);
    if (timeScale !== 0) {
        spawnIntervalFrames = floor(spawnIntervalFrames / abs(timeScale));
    } else {
         return;
    }
    if (spawnIntervalFrames < 1) spawnIntervalFrames = 1;

    if (frameCount % spawnIntervalFrames === 0) {
        let spawnAttempts = 20;
        let coinSpawned = false;
        const coinMinDistSq = 30 * 30;

        while (spawnAttempts > 0 && !coinSpawned) {
            spawnAttempts--;

            let sx = player.x + random(-500, 500);
            let sz = player.z + random(-500, 500);

            let spawnCellX = floor(sx / cellSize);
            let spawnCellZ = floor(sz / cellSize);

            if (spawnCellX === currentPlayerCellX && spawnCellZ === currentPlayerCellZ) {
                continue;
            }

            let cellKey = `${spawnCellX},${spawnCellZ}`;
            if (cellCooldownTimestamps.has(cellKey)) {
                if (millis() - cellCooldownTimestamps.get(cellKey) < cellCooldownDuration) {
                    continue;
                } else {

                    cellCooldownTimestamps.delete(cellKey);
                }
            }

            let forward = createVector(cos(player.angleY), sin(player.angleY));
            let spawnDir = createVector(sx - player.x, sz - player.z);
            if (forward.dot(spawnDir.normalize()) > -0.2) continue;

            if (checkCollision(sx, sz)) continue;

            let tooClose = false;
            for (let c of coins) {
                let dSq = (sx - c.x)*(sx - c.x) + (sz - c.z)*(sz - c.z);
                if (dSq < coinMinDistSq) {
                    tooClose = true;
                    break;
                }
            }
            if (tooClose) continue;

             if (random(1) < 0.3 * coinSpawnMultiplier * baseCoinSpawnMultiplier) {
                coins.push({
                    x: sx,
                    y: floorY + 20,
                    z: sz,
                    angle: random(TWO_PI)
                });
                coinSpawned = true;
             }
        }
    }
}

