                if (dSq < rubyMinDistSq) {
                    tooCloseRuby = true;
                    break;
                }
            }
             if (tooCloseRuby) continue;

            let finalRubySpawnChance = rubyBaseSpawnChance * baseRubySpawnChanceMultiplier;

            if (random(1) < finalRubySpawnChance) {
                rubies.push({
                    x: sx,
                    y: floorY + 15,
                    z: sz,
                    angle: random(TWO_PI)
                });
                rubySpawned = true;
            }
        }
    }
}

function cleanupCellCooldownMap() {
    const now = millis();
    for (const [key, timestamp] of cellCooldownTimestamps.entries()) {
        if (now - timestamp >= cellCooldownDuration) {
            cellCooldownTimestamps.delete(key);
        }
    }
}

function drawEnemy() {
    if (enemy === null) return;

    const playerChunkX = floor(player.x / (cellSize * chunkSize));
    const playerChunkZ = floor(player.z / (cellSize * chunkSize));
    const enemyChunkX = floor(enemy.x / (cellSize * chunkSize));
