        gl.enable(gl.DEPTH_TEST);
        gl.depthMask(true);
        gl.disable(gl.BLEND);
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

    } else if (enemy.isDissolving) {
         gl.enable(gl.DEPTH_TEST);
         gl.depthMask(true);
         gl.enable(gl.BLEND);
         gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
         gl.disable(gl.POLYGON_OFFSET_FILL);

        if (bothDissolvingDueToAngel) {
            shader(lightDissolveShader);
            lightDissolveShader.setUniform('uMainTexture', enemyTexture);
            lightDissolveShader.setUniform('uNoiseTexture', noiseTexture);
            lightDissolveShader.setUniform('uDissolveThreshold', enemy.dissolveProgress);
            lightDissolveShader.setUniform('uEdgeColor', [1.0, 0.9, 0.5]);
            lightDissolveShader.setUniform('uTime', millis() / 1000.0);
        } else {
            shader(dissolveShader);
            dissolveShader.setUniform('uWallTexture', enemyTexture);
            dissolveShader.setUniform('uNoiseTexture', noiseTexture);
            dissolveShader.setUniform('uDissolveThreshold', enemy.dissolveProgress);
            dissolveShader.setUniform('uEdgeColor', [0.1, 0.7, 1.0]);
            dissolveShader.setUniform('uTime', millis() / 1000.0);
        }

        model(enemyModel);
        resetShader();
        gl.disable(gl.BLEND);

    } else {
         gl.enable(gl.DEPTH_TEST);
         gl.depthMask(true);
         gl.disable(gl.BLEND);
         gl.disable(gl.POLYGON_OFFSET_FILL);
        resetShader();
        texture(enemyTexture);
        model(enemyModel);
    }
    pop();
}

