function spawnEnemy() {
    if (enemy !== null) return;

    let playerCellX = floor(player.x / cellSize);
    let playerCellZ = floor(player.z / cellSize);

    let spawnX = player.x;
    let spawnZ = player.z;
    let foundValidSpawn = false;
    let attempts = 100;

    const playerForward = createVector(cos(player.angleY), 0, sin(player.angleY)).normalize();
    const behindDotThreshold = -0.3;

    while (attempts > 0 && !foundValidSpawn) {
        attempts--;

        let spawnDist = random(MIN_INITIAL_SPAWN_DISTANCE, MAX_INITIAL_SPAWN_DISTANCE);
        let angle = random(TWO_PI);

        let potentialX = player.x + cos(angle) * spawnDist;
        let potentialZ = player.z + sin(angle) * spawnDist;

        let dirToSpawn = createVector(potentialX - player.x, 0, potentialZ - player.z).normalize();
        let dotProd = playerForward.dot(dirToSpawn);

        if (dotProd > behindDotThreshold) {
             continue;
        }

        let cx = floor(potentialX / cellSize);
        let cz = floor(potentialZ / cellSize);
        if (!isCellOpen(cx, cz)) {
            continue;
        }

        let potentialSpawnPointX = (cx + 0.5) * cellSize;
        let potentialSpawnPointZ = (cz + 0.5) * cellSize;
        if (checkCollisionForEnemy(potentialSpawnPointX, potentialSpawnPointZ)) {
             continue;
        }

        spawnX = potentialSpawnPointX;
        spawnZ = potentialSpawnPointZ;
        foundValidSpawn = true;
        break;
    }

    if (!foundValidSpawn) {
        console.warn("SpawnEnemy: Could not find ideal spot after 100 attempts. Using fallback teleport logic.");

        let fallbackAttempts = 30;
        while (fallbackAttempts-- > 0 && !foundValidSpawn) {
             const angle = random(TWO_PI);
             const dist = random(MIN_INITIAL_SPAWN_DISTANCE, MAX_INITIAL_SPAWN_DISTANCE);
             const spotX = player.x + cos(angle) * dist;
             const spotZ = player.z + sin(angle) * dist;

             const dirToSpotNorm = createVector(spotX - player.x, 0, spotZ - player.z).normalize();
             const dotForwardSpot = playerForward.dot(dirToSpotNorm);

             if (dotForwardSpot > behindDotThreshold) continue;

             const cellX = floor(spotX / cellSize);
             const cellZ = floor(spotZ / cellSize);
             if (!isCellOpen(cellX, cellZ)) continue;

             let fallbackCheckX = (cellX + 0.5) * cellSize;
             let fallbackCheckZ = (cellZ + 0.5) * cellSize;
             if (checkCollisionForEnemy(fallbackCheckX, fallbackCheckZ)) continue;

             spawnX = fallbackCheckX;
             spawnZ = fallbackCheckZ;
             foundValidSpawn = true;
             break;
        }

         if (!foundValidSpawn) {
             console.error("SpawnEnemy: Fallback teleport failed. Placing enemy at nearest open cell far behind player.");
             teleportEnemyToNearestOpenCellFarFrom(player.x - playerForward.x * MAX_INITIAL_SPAWN_DISTANCE, player.z - playerForward.z * MAX_INITIAL_SPAWN_DISTANCE);
             return;
         }
    }

    enemy = {
        x: spawnX,
        y: floorY,
        z: spawnZ,
        angleY: 0,
        aiState: 'searching',
        lastPosition: createVector(spawnX, floorY, spawnZ),
        stuckTimer: 0,
        isDissolving: false,
        dissolveProgress: 0.0
    };

    enemyPath = [];
    enemyLastTargetCell = { x: -1, z: -1 };
    enemyAISearchTarget = null;
    enemyAISearchTimer = 0;
    enemyChaseTimer = 0;
    enemyLastKnownPlayerPos = null;
}

