function updateAngelFollower(dt) {
    if (!angelFollower || playerDead || noclip || showMainMenu || dt <= 0) return;

    let effectiveSpeedFactor = timeScale > 0 ? timeScale : (timeScale < 0 ? 1 / Math.abs(timeScale) : 0);
    if (effectiveSpeedFactor === 0) return;

    if (angelFollower.isDissolving) {
        angelFollower.dissolveProgress += ANGEL_DISSOLVE_RATE * effectiveSpeedFactor * dt;
        angelFollower.dissolveProgress = min(angelFollower.dissolveProgress, 1.0);
        if (angelFollower.dissolveProgress >= 1.0) {
            despawnAngelFollower();
        }
        return;
    }

    if (bothDissolvingDueToAngel) { 
        return;
    }

    checkAngelEnemyCollision();
    if (angelFollower.isDissolving || bothDissolvingDueToAngel) return;

    let targetXForMovement, targetZForMovement;
    let targetXForLooking, targetZForLooking;
    let newAiState = angelFollower.aiState;
    let shouldMove = true;

    if (enemy && enemyIsAwareOfPlayer && !enemy.isDissolving && !isEnergyShieldActive) {
        newAiState = 'attacking_enemy';
        targetXForMovement = enemy.x;
        targetZForMovement = enemy.z;
        targetXForLooking = enemy.x;
        targetZForLooking = enemy.z;
        angelFollower.currentTarget = enemy;
    } else {
        let closestItem = null;
        let closestDistSq = ANGEL_COLLECTION_RANGE_SQ;

        for (let coin of coins) {
            let distSq = (coin.x - angelFollower.x) ** 2 + (coin.z - angelFollower.z) ** 2;
            if (distSq < closestDistSq) {
                closestDistSq = distSq;
                closestItem = coin;
            }
        }
        for (let ruby of rubies) {
            let distSq = (ruby.x - angelFollower.x) ** 2 + (ruby.z - angelFollower.z) ** 2;
            if (distSq < closestDistSq) {
                closestDistSq = distSq;
                closestItem = ruby;
            }
        }

        if (closestItem) {
            newAiState = 'collecting_items';
            targetXForMovement = closestItem.x;
            targetZForMovement = closestItem.z;
            targetXForLooking = closestItem.x;
            targetZForLooking = closestItem.z;
            angelFollower.currentTarget = closestItem;
        } else {
            newAiState = 'following_player';
            angelFollower.currentTarget = null;
            let distToPlayer = dist(angelFollower.x, angelFollower.z, player.x, player.z);

            if (distToPlayer > ANGEL_FOLLOW_DISTANCE) {
                targetXForMovement = player.x;
                targetZForMovement = player.z;
            } else if (distToPlayer > ANGEL_FOLLOW_STOP_DISTANCE) {
                 targetXForMovement = player.x;
                 targetZForMovement = player.z;
            }
             else {
                targetXForMovement = angelFollower.x;
                targetZForMovement = angelFollower.z;
                shouldMove = false; 
            }
            targetXForLooking = player.x;
            targetZForLooking = player.z;
        }
    }
    angelFollower.aiState = newAiState;

    if (shouldMove) {
        let targetCellX = floor(targetXForMovement / cellSize);
        let targetCellZ = floor(targetZForMovement / cellSize);
        let angelCellX = floor(angelFollower.x / cellSize);
        let angelCellZ = floor(angelFollower.z / cellSize);

        if (targetCellX !== angelFollowerLastTargetCell.x || targetCellZ !== angelFollowerLastTargetCell.z || angelFollowerPath.length < 2) {
            if (angelCellX !== targetCellX || angelCellZ !== targetCellZ) {
                const newPath = findPath(angelCellX, angelCellZ, targetCellX, targetCellZ);
                if (newPath && newPath.length > 1) {
                    angelFollowerPath = newPath;
                } else {
                    angelFollowerPath = [];
                }
            } else {
                angelFollowerPath = [];
            }
            angelFollowerLastTargetCell.x = targetCellX;
            angelFollowerLastTargetCell.z = targetCellZ;
        }

        let actualTargetX = targetXForMovement;
        let actualTargetZ = targetZForMovement;

        if (angelFollowerPath.length > 1) {
            const nextNode = angelFollowerPath[1];
            actualTargetX = (nextNode.x + 0.5) * cellSize;
            actualTargetZ = (nextNode.z + 0.5) * cellSize;
        }

        let dir = createVector(actualTargetX - angelFollower.x, 0, actualTargetZ - angelFollower.z);
        let distanceToActualTarget = dir.mag();

        let movementThreshold = ANGEL_FOLLOWER_RADIUS * 0.5;
        if (angelFollower.aiState === 'following_player' && !shouldMove) {
             movementThreshold = 0.1;
        }

        if (distanceToActualTarget > movementThreshold) {
            dir.normalize();
            let moveSpeed = ANGEL_FOLLOWER_SPEED * ANGEL_FOLLOWER_STEP_SIZE * effectiveSpeedFactor;
            let displacementMagnitude = moveSpeed * dt;

            let moveX = dir.x * displacementMagnitude;
            let moveZ = dir.z * displacementMagnitude;
            let nextX = angelFollower.x + moveX;
            let nextZ = angelFollower.z + moveZ;

            let originalX = angelFollower.x;
            let originalZ = angelFollower.z;

            if (!checkCollisionForEnemy(nextX, originalZ)) {
                angelFollower.x = nextX;
            }
            if (!checkCollisionForEnemy(angelFollower.x, nextZ)) {
                angelFollower.z = nextZ;
            }
        }

        if (angelFollowerPath.length > 1) {
            let nextNodeTargetX = (angelFollowerPath[1].x + 0.5) * cellSize;
            let nextNodeTargetZ = (angelFollowerPath[1].z + 0.5) * cellSize;
            let distToNextNodeSq = (nextNodeTargetX - angelFollower.x) ** 2 + (nextNodeTargetZ - angelFollower.z) ** 2;
            let nodeReachedThresholdSq = (cellSize * ANGEL_FOLLOWER_STEP_SIZE * 0.7) ** 2;
            if (distToNextNodeSq < nodeReachedThresholdSq) {
                angelFollowerPath.shift();
            }
        }
    }

    let lookDx = targetXForLooking - angelFollower.x;
    let lookDz = targetZForLooking - angelFollower.z;
    if (abs(lookDx) > 0.1 || abs(lookDz) > 0.1) {
        angelFollower.angleY = atan2(lookDz, lookDx);
    }

    angelFollower.y = floorY;

    for (let i = coins.length - 1; i >= 0; i--) {
        let coin = coins[i];
        let dxAngel = angelFollower.x - coin.x;
        let dzAngel = angelFollower.z - coin.z;
        let distanceSqAngel = dxAngel * dxAngel + dzAngel * dzAngel;
        if (distanceSqAngel < (ANGEL_FOLLOWER_RADIUS * 2.5) * (ANGEL_FOLLOWER_RADIUS * 2.5)) { 
            coins.splice(i, 1);
            coinsCollectedThisRound++;
            totalCoinsAllTime++;
            if (collectCoinSound) collectCoinSound.play(0, 1, fxVolume);
        }
    }
    for (let i = rubies.length - 1; i >= 0; i--) {
        let ruby = rubies[i];
        let dxAngel = angelFollower.x - ruby.x;
        let dzAngel = angelFollower.z - ruby.z;
        let distanceSqAngel = dxAngel * dxAngel + dzAngel * dzAngel;
        if (distanceSqAngel < (ANGEL_FOLLOWER_RADIUS * 2.5) * (ANGEL_FOLLOWER_RADIUS * 2.5)) {
            rubies.splice(i, 1);
            coinsCollectedThisRound += 100;
            totalCoinsAllTime += 100;
            if (collectCoinSound) collectCoinSound.play(0, 1, fxVolume * 0.8);
        }
    }
}

