function checkAngelEnemyCollision() {
    if (!angelFollower || !enemy || angelFollower.isDissolving || enemy.isDissolving || bothDissolvingDueToAngel) return;

    let distSq = (angelFollower.x - enemy.x) ** 2 + (angelFollower.z - enemy.z) ** 2;
    let collisionRadius = ANGEL_FOLLOWER_RADIUS + playerRadius;
    if (distSq < collisionRadius * collisionRadius) {
        angelFollower.isDissolving = true;
        angelFollower.dissolveProgress = 0.01;

        enemy.isDissolving = true;
        enemy.dissolveProgress = 0.01;
        enemy.aiState = 'idle_dissolving';
        enemyPath = [];

        bothDissolvingDueToAngel = true;

        if (iWillBeBackSound) {
            iWillBeBackSound.play(0, 1, fxVolume);
        }

        enemyRespawnScheduledAfterShield = true;
        enemyRespawnTimer = 15.0;
        initialEnemySpawnScheduled = false;
    }
}

