        sonarEnemyShader.setUniform('uGridDensity', 12.0);
        sonarEnemyShader.setUniform('uGridThickness', 0.03); 
        sonarEnemyShader.setUniform('uGridPulseSpeed', 7.0);
        sonarEnemyShader.setUniform('uGridPulseAmount', 0.015);

        model(enemyModel);          

        resetShader();
        gl.enable(gl.DEPTH_TEST);
        gl.depthMask(true);
        gl.disable(gl.BLEND);
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA); 

    } else if (enemy.isDissolving) {

         gl.enable(gl.DEPTH_TEST);
         gl.depthMask(true);
         gl.enable(gl.BLEND);
         gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
         gl.disable(gl.POLYGON_OFFSET_FILL);

        shader(dissolveShader);
        dissolveShader.setUniform('uWallTexture', enemyTexture);
        dissolveShader.setUniform('uNoiseTexture', noiseTexture);
        dissolveShader.setUniform('uDissolveThreshold', enemy.dissolveProgress);
        dissolveShader.setUniform('uEdgeColor', [0.1, 0.7, 1.0]);
        dissolveShader.setUniform('uTime', millis() / 1000.0);

        model(enemyModel);

        resetShader();
        gl.disable(gl.BLEND);

    } else {

         gl.enable(gl.DEPTH_TEST);
         gl.depthMask(true);
         gl.disable(gl.BLEND);
         gl.disable(gl.POLYGON_OFFSET_FILL);
        resetShader();
        texture(enemyTexture);

        model(enemyModel);
    }

    pop();
}

function keyPressed() {

    if (keyCode === 121) {
        isConsoleVisible = !isConsoleVisible;
        if (isConsoleVisible) {
            cursor();
            if (isPointerLocked) document.exitPointerLock();
        } else {

            if (!showMainMenu && !playerDead) {
                 canvas.elt.requestPointerLock();
                 noCursor();
            } else {
                 cursor();
            }
        }
        return;
    }

    if (isConsoleVisible) {
        handleConsoleKeyPressed();
        return;
    }

    if (!showMainMenu && !playerDead) {

        if (key === 'w' || key === 'W' || keyCode === UP_ARROW) moveForward = true;
        if (key === 's' || key === 'S' || keyCode === DOWN_ARROW) moveBackward = true;
        if (key === 'a' || key === 'A' || keyCode === LEFT_ARROW) moveLeft = true;
        if (key === 'd' || key === 'D' || keyCode === RIGHT_ARROW) moveRight = true;

        if (noclip) {
             if (key === 'e' || key === 'E') moveUp = true;
             if (key === 'q' || key === 'Q') moveDown = true;
        } else if (isFlyingWithWings) {
             if (key === 'e' || key === 'E') moveUp = false;
             if (key === 'q' || key === 'Q') moveDown = false;
             if (keyCode === 32) spacePressed = false;
        }
        else {

            if (key === 'e' || key === 'E') {
                if (!slowMotionActive && slowMotionMeterValue >= 1.0) {
                    timeScale = 0.5;
                    slowMotionActive = true;
                    slowMotionRemainingTime = instinctDuration;
                }
            }

             if (keyCode === 32) {
                spacePressed = true;

             }
        }

        if (keyCode === SHIFT && !isFlyingWithWings) running = true;

        if (keyCode >= 49 && keyCode <= 57) {
            let itemIndex = keyCode - 49;
            if (itemIndex < prestigeItems.length) {
                let item = prestigeItems[itemIndex];

                if (item.purchased && !item.isActive && !item.isOnCooldown) {
                    item.isActive = true;
                    item.activeTimer = item.baseDuration;
                    item.isOnCooldown = false;
                    item.cooldownTimer = 0;

                    if (item.id === 0) {
                        wallPassActive = true;
                        noclip = false;
                        isFlyingWithWings = false;
                        if(angelWingsSound && angelWingsSound.isLooping()) angelWingsSound.stop();
                        consoleCurrentLine = "wallpass 1";
                        handleConsoleCommand(true);
                        consoleCurrentLine = "";
                    } else if (item.id === 1) {
                        isEnergyShieldActive = true;
                        if (energyShieldSound) {
                            energyShieldSound.play(0, 1, fxVolume);
                        }
                    } else if (item.id === 2) {
                        if (sonarSound) {
                            sonarSound.loop(0, 1, fxVolume);
                        }
                    } else if (item.id === 3) {
                        isFlyingWithWings = true;
                        targetFlyHeight = floorY - angelWingsFlyHeight;
                        noclip = false;
                        wallPassActive = false;
                        for (const key in mazeChunks) {
                            const chunk = mazeChunks[key];
                            if (chunk.dissolveState) {
                                 for(let i = 0; i < chunk.dissolveState.length; i++) {
                                     for (let j = 0; j < chunk.dissolveState[i].length; j++) {
                                         chunk.dissolveState[i][j] = 0.0;
                                     }
                                 }
                             }
                         }
                         if (checkCollision(player.x, player.z)) {
                             teleportToNearestOpenCell();
                         }
                        if (angelWingsSound) {
                            angelWingsSound.loop(0, 1, fxVolume);
                        }
                    } else if (item.id === 4) {
                        spawnAngelFollower();
                        if(angelSpawnSound) {
                            angelSpawnSound.play(0, 1, fxVolume);
                        }
                    }
                }
            }
        }
    }
}

function keyReleased() {
    if (isConsoleVisible) return;

    if (key === 'w' || key === 'W' || keyCode === UP_ARROW) moveForward = false;
    if (key === 's' || key === 'S' || keyCode === DOWN_ARROW) moveBackward = false;
    if (key === 'a' || key === 'A' || keyCode === LEFT_ARROW) moveLeft = false;
    if (key === 'd' || key === 'D' || keyCode === RIGHT_ARROW) moveRight = false;
    if (key === 'q' || key === 'Q') moveDown = false;
    if (key === 'e' || key === 'E') moveUp = false;

    if (keyCode === SHIFT) running = false;
    if (keyCode === 32) {
        spacePressed = false;
    }
}

