function drawConsoleOverlay() {
    push(); 
    resetMatrix(); 
    resetCustomCamera(); 

    ortho(-width / 2, width / 2, -height / 2, height / 2, -1000, 1000);

    fill(consoleBgColor);
    noStroke();
    rect(consoleX, consoleY, consoleWidth, consoleHeight);

    fill(30);
    rect(consoleX, consoleY, consoleWidth, consoleTitleHeight);
    fill(255);
    textSize(consoleFontSize);
    textFont(consoleFont);
    textAlign(LEFT, CENTER);
    text("Command Prompt", consoleX + 10, consoleY + consoleTitleHeight / 2);

    let textYStart = consoleY + consoleTitleHeight + 5;
    let textYEnd = consoleY + consoleHeight - 5;
    let viewableTextHeight = textYEnd - textYStart;
    let textHeight = calculateConsoleTextHeight();
    let isOverflow = textHeight > viewableTextHeight;

    push(); 
    let yPos = textYStart - consoleScrollY; 
    let textX = consoleX + 10;

    fill(255);
    textSize(consoleFontSize);
    textFont(consoleFont);
    textAlign(LEFT, TOP);

    for (let i = 0; i < consoleTextLines.length; i++) {

        let wrappedLines = getWrappedConsoleLines(consoleTextLines[i], consoleWidth - 20);
        for (let j = 0; j < wrappedLines.length; j++) {

            if (yPos >= textYStart && yPos <= textYEnd) {
                text(wrappedLines[j], textX, yPos);
            }
            yPos += consoleFontSize + 1; 
        }
    }

    if (frameCount % 30 === 0) consoleCursorBlink = !consoleCursorBlink;

    if (yPos >= textYStart && yPos <= textYEnd) {
        let cursorText = consoleCurrentLine;
        if (consoleCursorBlink) cursorText += "_";
        text(cursorText, textX, yPos);
    }
    pop(); 

    if (isOverflow) {
        fill(200);
        noStroke();
        let scrollBarHeight = (viewableTextHeight * viewableTextHeight) / textHeight;
        let scrollBarY = map(consoleScrollY, 0, textHeight - viewableTextHeight, textYStart, textYEnd - scrollBarHeight);
        rect(consoleX + consoleWidth - 10, scrollBarY, 8, scrollBarHeight);
    }

    if (consoleSelectionStart !== null && consoleSelectionEnd !== null) {
        highlightConsoleSelectedText();
    }

    pop(); 
}

function handleConsoleKeyPressed() {
    if (keyCode === BACKSPACE) {

        if (consoleCurrentLine.length > 0) {
            consoleCurrentLine = consoleCurrentLine.slice(0, -1);
        }
    } else if (keyCode === ENTER) {

        let commandLine = consoleCurrentLine.trim();
        if (commandLine !== "") {
            consoleHistory.push(commandLine); 
            consoleHistoryIndex = -1; 
        }
        handleConsoleCommand(); 
        consoleTextLines.push("> " + consoleCurrentLine); 
        consoleCurrentLine = ""; 
        scrollConsoleToBottom(); 
    } else if (keyCode === UP_ARROW) {

        if (consoleHistory.length > 0) {
            if (consoleHistoryIndex === -1) {
                consoleHistoryIndex = consoleHistory.length - 1;
            } else if (consoleHistoryIndex > 0) {
                consoleHistoryIndex--;
            }
            consoleCurrentLine = consoleHistory[consoleHistoryIndex] || "";
        }
    } else if (keyCode === DOWN_ARROW) {

        if (consoleHistory.length > 0 && consoleHistoryIndex !== -1) {
            consoleHistoryIndex++;
            if (consoleHistoryIndex >= consoleHistory.length) {
                consoleHistoryIndex = -1;
                consoleCurrentLine = "";
            } else {
                consoleCurrentLine = consoleHistory[consoleHistoryIndex];
            }
        }
    } else if (keyCode === 67 && keyIsDown(CONTROL)) { 

        if (consoleSelectionStart !== null && consoleSelectionEnd !== null) {
            copySelectedConsoleText();
        }
    } else if (keyCode === 86 && keyIsDown(CONTROL)) { 

        let input = prompt("Paste your text here:");
        if (input !== null) {
            let pastedLines = input.split('\n');
            if (pastedLines.length > 0) {
                consoleCurrentLine += pastedLines[0];
                for (let i = 1; i < pastedLines.length; i++) {
                    consoleTextLines.push(consoleCurrentLine);
                    consoleCurrentLine = pastedLines[i];
                }
                scrollConsoleToBottom();
            }
        }
    }
}

function handleConsoleCommand(bypassAdminCheck = false) {
    let commandLine = consoleCurrentLine.trim();
    if (commandLine === "") return;

    let tokens = commandLine.split(" ");
    let command = tokens[0].toLowerCase();
    let args = tokens.slice(1);

    const adminBypassCommands = ["wallpass"];

    if (!isAdmin && !bypassAdminCheck && !["help", "clear", "date", "adminlogin"].includes(command)) {
         consoleTextLines.push("Login As System Admin First");
         consoleCurrentLine = "";
         scrollConsoleToBottom();
         return;
     }

     if (!isAdmin && bypassAdminCheck && !adminBypassCommands.includes(command)) {
         consoleTextLines.push("Error: This command cannot be bypassed without admin privileges.");
         consoleCurrentLine = "";
         scrollConsoleToBottom();
         return;
     }

    switch (command) {
        case "date":
            consoleTextLines.push(new Date().toString());
            break;

        case "help":
            consoleTextLines.push("Available commands:");
            consoleTextLines.push("  adminlogin <password>");
            consoleTextLines.push("  date");
            consoleTextLines.push("  help");
            consoleTextLines.push("  clear");
            consoleTextLines.push("  speed <1-10>");
            consoleTextLines.push("  noclip <0|1>");
            consoleTextLines.push("  wallpass <0|1>");
            consoleTextLines.push("  renderdistance <1-3>");
            consoleTextLines.push("  minimapzoom <1-3>");
            consoleTextLines.push("  spawnenemy");
            consoleTextLines.push("  despawnenemy");
            consoleTextLines.push("  coinspawnrate <1-10>");
            consoleTextLines.push("  rubyspawnrate <1-10>");
            consoleTextLines.push("  coinspawn <0|1>");
            consoleTextLines.push("  bossrage <1-3>");
            consoleTextLines.push("  setskullcoins <0-999999>");
            consoleTextLines.push("  addprestigetokens <amount>");
            consoleTextLines.push("  coinmagnet <0-10>");
            consoleTextLines.push("  timescale <-10-10>");
            consoleTextLines.push("  debug <0|1>");
            break;

        case "clear":
            consoleTextLines = [];
            consoleCurrentLine = "";
            consoleScrollY = 0;
            break;

        case "adminlogin":
            if (args.length !== 1) {
                consoleTextLines.push("Error: adminlogin requires exactly one argument.");
                break;
            }
            {
                let hiddenPasswordChars = [107, 102, 99, 110, 117, 103, 103, 101, 116];
                let hiddenPassword = String.fromCharCode(...hiddenPasswordChars);
                let passwordAttempt = args[0];
                if (passwordAttempt === hiddenPassword) {
                    isAdmin = true;
                    consoleTextLines.push("Welcome System Admin");
                } else {
                    consoleTextLines.push("Wrong Password");
                }
            }
            break;

        case "speed":
            if (!isAdmin && !bypassAdminCheck) { consoleTextLines.push("Login As System Admin First"); break; }
            if (args.length !== 1) {
                consoleTextLines.push("Error: speed command requires exactly one argument.");
                break;
            }
            {
                let speedArg = parseInt(args[0]);
                if (isNaN(speedArg) || speedArg < 1 || speedArg > 10) {
                    consoleTextLines.push("Error: Please choose a numerical value between 1 to 10.");
                    break;
                }

                speedUpgradeLevel = speedArg - 1;
                speedMultiplier = Math.pow(1.1, speedUpgradeLevel);
                baseSpeed = DEFAULT_PER_SECOND_SPEED * speedMultiplier;
                currentSpeed = baseSpeed * momentum;
                consoleTextLines.push("Speed level set to " + (speedUpgradeLevel + 1) + " (Base Speed: " + baseSpeed.toFixed(2) + ")");
            }
            break;

        case "noclip":
             if (!isAdmin && !bypassAdminCheck) { consoleTextLines.push("Login As System Admin First"); break; }
            if (args.length !== 1) {
                consoleTextLines.push("Error: noclip command requires exactly one argument: 1 to enable, 0 to disable.");
                break;
            }
            {
                let noclipArg = args[0];
                if (noclipArg === '1') {
                    noclip = true;
                    if (prestigeItems[0] && prestigeItems[0].isActive) {
                         prestigeItems[0].isActive = false;
                         prestigeItems[0].activeTimer = 0;
                         wallPassActive = false;
                         consoleTextLines.push("Wall Pass deactivated due to Noclip.");
                         if (checkCollision(player.x, player.z)) {
                            teleportToNearestOpenCell();
                         }
                    }
                    consoleTextLines.push("Noclip mode enabled.");
                } else if (noclipArg === '0') {
                    noclip = false;
                    consoleTextLines.push("Noclip mode disabled.");
                    player.y = floorY;
                    if (checkCollision(player.x, player.z)) {
                        teleportToNearestOpenCell();
                        consoleTextLines.push("Teleported to prevent being stuck in a wall.");
                    }
                } else {
                    consoleTextLines.push("Error: The only available inputs for noclip are 1 and 0.");
                }
            }
            break;

        case "wallpass":

             if (!isAdmin && !bypassAdminCheck) { consoleTextLines.push("Login As System Admin First"); break; }
             if (args.length !== 1) {
                 consoleTextLines.push("Error: wallpass command requires exactly one argument: 0 or 1.");
                 break;
             }
             {
                 let passArg = args[0];
                 if (passArg === '1') {
                     wallPassActive = true;
                     noclip = false;
                     if (!bypassAdminCheck) consoleTextLines.push("Wall Pass mode enabled.");
                 } else if (passArg === '0') {
                     wallPassActive = false;

                      for (const key in mazeChunks) {
                         const chunk = mazeChunks[key];
                         if (chunk.dissolveState) {
                              for(let i = 0; i < chunk.dissolveState.length; i++) {
                                  for (let j = 0; j < chunk.dissolveState[i].length; j++) {
                                      chunk.dissolveState[i][j] = 0.0;
                                  }
                              }
                          }
                      }
                     if (!bypassAdminCheck) consoleTextLines.push("Wall Pass mode disabled.");
                      if (checkCollision(player.x, player.z)) {
                        teleportToNearestOpenCell();
                        if (!bypassAdminCheck) consoleTextLines.push("Teleported to prevent being stuck in a wall.");
                    }
                 } else {
                     consoleTextLines.push("Error: The only available inputs for wallpass are 1 and 0.");
                 }
             }
             break;

        case "renderdistance":
             if (!isAdmin && !bypassAdminCheck) { consoleTextLines.push("Login As System Admin First"); break; }
            if (args.length !== 1) {
                consoleTextLines.push("Error: renderdistance command requires exactly one argument between 1 and 3.");
                break;
            }
            {
                let rdArg = parseInt(args[0]);
                if (isNaN(rdArg) || rdArg < 1 || rdArg > 3) {
                    consoleTextLines.push("Error: renderdistance must be a number between 1 and 3.");
                } else {
                    renderDistance = rdArg;
                    consoleTextLines.push("Render distance set to " + rdArg);
                }
            }
            break;

        case "minimapzoom":
