function getConsoleCharIndexAtMouse(line, mouseXPos) {
    let xOffset = mouseXPos - (consoleX + 10);
    if (xOffset < 0) return 0;
    let cumulativeWidth = 0;
    for (let i = 0; i < line.length; i++) {
        cumulativeWidth += textWidth(line[i]);
        if (cumulativeWidth >= xOffset) {
            return i;
        }
    }
    return line.length;
}

function getWrappedConsoleLines(text, maxWidth) {
    let lines = [];
    let currentLine = '';

    for (let i = 0; i < text.length; i++) {
        let testLine = currentLine + text[i];
        if (textWidth(testLine) > maxWidth) {
            if (currentLine.length > 0) {
                lines.push(currentLine);
                currentLine = text[i];
            } else {
                lines.push(text[i]);
                currentLine = '';
            }
        } else {
            currentLine = testLine;
        }
    }
    if (currentLine) lines.push(currentLine);
    return lines;
}

function scrollConsoleToBottom() {
    let textHeight = calculateConsoleTextHeight();
    let viewableTextHeight = consoleHeight - consoleTitleHeight - 20;
    let isOverflow = textHeight > viewableTextHeight;
    if (isOverflow) {
        consoleScrollY = max(0, textHeight - viewableTextHeight);
    }
