function calculateConsoleTextHeight() {
    let textHeight = 0;
    let yPos = consoleY + consoleTitleHeight + 5;
    textSize(consoleFontSize);
    for (let i = 0; i < consoleTextLines.length; i++) {
        let textLine = consoleTextLines[i];
        let wrappedLines = getWrappedConsoleLines(textLine, consoleWidth - 20);
        for (let j = 0; j < wrappedLines.length; j++) {
            yPos += consoleFontSize + 1;
        }
    }
    let wrappedLines = getWrappedConsoleLines(consoleCurrentLine, consoleWidth - 20);
    for (let j = 0; j < wrappedLines.length; j++) {
        yPos += consoleFontSize + 1;
    }

    textHeight = (yPos - (consoleY + consoleTitleHeight + 5));
    consoleMaxScrollY = textHeight;
    return textHeight;
}

