function teleportToNearestOpenCell() {
    let minDistance = Infinity;
    let targetX = player.x;
    let targetZ = player.z;

    for (const key in mazeChunks) {
        const chunk = mazeChunks[key];
        const chunkX = chunk.chunkX;
        const chunkZ = chunk.chunkZ;
        const maze = chunk.maze;

        const baseX = chunkX * chunkSize * cellSize;
        const baseZ = chunkZ * chunkSize * cellSize;

        for (let i = 0; i < chunkSize; i++) {
            for (let j = 0; j < chunkSize; j++) {
                if (maze[i][j] === 0) { 
                    const cellX = (chunkX * chunkSize + i + 0.5) * cellSize;
                    const cellZ = (chunkZ * chunkSize + j + 0.5) * cellSize;
                    const distance = dist(player.x, player.z, cellX, cellZ);
                    if (distance < minDistance) {
                        minDistance = distance;
                        targetX = cellX;
                        targetZ = cellZ;
                    }
                }
            }
        }
    }

    player.x = targetX;
    player.z = targetZ;
    player.y = 150; 
    resetMomentum();
}

