function isCellOpen(cx, cz) {

	const chunkX = floor(cx / chunkSize);
	const chunkZ = floor(cz / chunkSize);
	const key = chunkX + "," + chunkZ;

	const chunk = mazeChunks[key];
	if (!chunk) return false;

	let localX = cx % chunkSize;
	let localZ = cz % chunkSize;
	if (localX < 0) localX += chunkSize;
	if (localZ < 0) localZ += chunkSize;

	if (localX < 0 || localX >= chunkSize || localZ < 0 || localZ >= chunkSize) return false;

	return (chunk.maze[localX][localZ] === 0);
}

function findPath(startX, startZ, goalX, goalZ) {
    if (startX === goalX && startZ === goalZ) {
        return [{ x: startX, z: startZ }];
    }

    const encode = (x, z) => `${x},${z}`;
    const decode = s => s.split(",").map(Number);

    const openSet = new Map();
    const cameFrom = new Map(); 
    const gScore = new Map();   
    const fScore = new Map();   

    const startKey = encode(startX, startZ);
    gScore.set(startKey, 0);
    fScore.set(startKey, abs(startX - goalX) + abs(startZ - goalZ));
    openSet.set(startKey, true); 

    const dirs = [[0, -1], [1, 0], [0, 1], [-1, 0]]; 

    const MAX_ITERATIONS = 5000; 
    let iterations = 0;

    while (openSet.size > 0) {
        iterations++;
        if (iterations > MAX_ITERATIONS) {
            console.error(`findPath Error: Exceeded MAX_ITERATIONS (${MAX_ITERATIONS}) from (${startX},${startZ}) to (${goalX},${goalZ}). Aborting.`);
            return null;
        }

        let currentKey = null;
        let lowestFScore = Infinity;
        for (const k of openSet.keys()) {
             let score = fScore.get(k) || Infinity;
            if (score < lowestFScore) {
                lowestFScore = score;
                currentKey = k;
            }
        }

        if (currentKey === null) {

            return null;
        }

        const [currentX, currentZ] = decode(currentKey);

        if (currentX === goalX && currentZ === goalZ) {

            const path = [];
            let reconstructKey = currentKey; 
            let reconstructSafety = 0;

            while (reconstructKey !== startKey && reconstructSafety < MAX_ITERATIONS) {
                 if (!reconstructKey || !cameFrom.has(reconstructKey)) {

                     console.error(`A* Error: Path reconstruction failed. Missing node or cameFrom entry for key: ${reconstructKey}. Current Path:`, JSON.stringify(path));
                     return null; 
                 }
                 const [pX, pZ] = decode(reconstructKey);
                 path.push({ x: pX, z: pZ });
                 reconstructKey = cameFrom.get(reconstructKey); 
                 reconstructSafety++;
            }

            if (reconstructSafety >= MAX_ITERATIONS) {
                 return null;
            }

            const [sX, sZ] = decode(startKey);
            path.push({ x: sX, z: sZ});

            if (path.length === 0) {
                 return null;
            }

            return path.reverse(); 

        }

        openSet.delete(currentKey); 

        for (const [dX, dZ] of dirs) {
            const neighborX = currentX + dX;
            const neighborZ = currentZ + dZ;
            const neighborKey = encode(neighborX, neighborZ);

            if (!isCellOpen(neighborX, neighborZ)) {
                continue;
            }

            const tentativeGScore = (gScore.get(currentKey) || 0) + 1; 
            const currentNeighborGScore = gScore.get(neighborKey) || Infinity; 

            if (tentativeGScore < currentNeighborGScore) {

                cameFrom.set(neighborKey, currentKey); 
                gScore.set(neighborKey, tentativeGScore);
                fScore.set(neighborKey, tentativeGScore + abs(neighborX - goalX) + abs(neighborZ - goalZ));

                if (!openSet.has(neighborKey)) {
                    openSet.set(neighborKey, true); 
                }
            }
        } 
    } 

    return null; 
}

