function drawShopItem(label, x, y, price) {
	textFont(uiFont);

	fill(50);
	rectMode(CENTER);
	rect(x, y, 500, 40);

	fill(255);
	textSize(20);
	textAlign(LEFT, CENTER);
	text(label, x - 200, y);

	textAlign(CENTER, CENTER);

	if (price !== "MAX") {
		fill(100, 200, 100);
		rect(x + 130, y, 40, 40);
		fill(0);
		text("+", x + 130, y);
	} else {
		fill(100, 100, 100);
		rect(x + 130, y, 40, 40);
		fill(200);
		text("X", x + 130, y);
	}

	fill(255);
	textSize(16);
	textAlign(LEFT, CENTER);
	text(price, x + 160, y);
}

function resetAllShopUpgrades() {

	speedUpgradeLevel = 0;
	speedMultiplier = 1.0;
	baseSpeed = 3;
	currentSpeed = baseSpeed * momentum;

	coinSpawnUpgradeLevel = 0;
	coinSpawnRate = 1;
	coinSpawnMultiplier = map(coinSpawnRate, 1, 10, 1, 3.5);

	minimapZoomUpgradeLevel = 0;
