                prestigeItems[i].activeTimer = 0;
                prestigeItems[i].isOnCooldown = false;
                prestigeItems[i].cooldownTimer = 0;
            }
        } else {

            prestigeItems = [];
            for (let i = 0; i < 9; i++) {
                 let itemName = `Prestige Item ${i + 1}`;
                 let itemDuration = 0;
                 let itemCooldown = 0;
                 let itemDescription = `Placeholder description for item ${i + 1}.`;
                 if (i === 0) {
                     itemName = "Wall Pass";
                     itemDuration = wallPassDuration;
                     itemCooldown = wallPassCooldown;
                     itemDescription = "Phase through walls for 10 seconds.";
                 } else if (i === 1) {
                     itemName = "Energy Shield";
                     itemDuration = 6;
                     itemCooldown = 120;
                     itemDescription = "Invulnerable shield for 6 seconds. Vaporizes enemy on contact.";
                 } else if (i === 2) {
                    itemName = "Sonar";
                    itemDuration = 30;
                    itemCooldown = 360;
                    itemDescription = "Reveal enemy and rubies through walls for 30 seconds.";
                } else if (i === 3) {
                    itemName = "Angel Wings";
                    itemDuration = 25;
                    itemCooldown = 60;
                    itemDescription = "Fly fast, ignoring wall slowdown for 25 seconds.";
                }

                prestigeItems.push({
                    id: i,
                    name: itemName,
                    price: prestigeItemPrices[i],
                    purchased: false,
                    description: itemDescription,
                    isActive: false,
                    activeTimer: 0,
