                } else if (i === 2) {
                    if (minimapZoomUpgradeLevel < 2) {
                        let cost = (minimapZoomUpgradeLevel === 0) ? 7500 : 25000;
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            minimapZoomUpgradeLevel++;
                            if (minimapZoomUpgradeLevel === 1) minimapZoomLevel = 2;
                            else if (minimapZoomUpgradeLevel === 2) minimapZoomLevel = 1;

                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                } else if (i === 3) {
                    if (coinMagnetLevel < 10) {
                        let cost = coinMagnetPrices[coinMagnetLevel];
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            coinMagnetLevel++;
                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                } else if (i === 4) {
                    if (instinctDurationUpgrades < maxInstinctDurationUpgrades) {
                        let cost = 100 + 10 * pow(instinctDurationUpgrades, 2);
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            instinctDurationUpgrades++;
                            instinctDuration = 5 + instinctDurationUpgrades;
                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                } else if (i === 5) {
                     if (instinctCooldownUpgrades < maxInstinctCooldownUpgrades) {
                        let cost = 100 + 10 * pow(instinctCooldownUpgrades, 2);
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            instinctCooldownUpgrades++;
                            instinctCooldown = 30 - instinctCooldownUpgrades;
                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                } else if (i === 6) {
                    if (maxLives < 10) {
                        let cost = maxLivesUpgradePrices[maxLives - 1];
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            maxLives++;
                            lives = maxLives;
                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                } else if (i === 7) {
                    if (rubySpawnRateSetting < 10) {
                        let cost = rubySpawnRateUpgradePrices[rubySpawnRateSetting - 1];
                        if (skullCoins >= cost) {
                            skullCoins -= cost;
                            skullCoinsSpentThisPrestige += cost;
                            rubySpawnRateSetting++;
                            purchased = true;
                        } else {
                            skullCoinsShake = true; skullCoinsShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                }
                if (purchased) {
                    playButtonClickSound();
                }
                return;
            }
        }

    } else if (currentMenu === "prestige") {
        let gridStartX = -190;
        let gridStartY = -height / 2 + 400;
        let itemWidth = 150;
        let itemHeight = 230;
        let spacingX = 25;
        let spacingY = 25;
        let purchaseButtonHeight = 30;

        let gridBottomY = gridStartY + (3 * itemHeight + 2 * spacingY) - itemHeight / 2;
        let prestigeTextY = gridBottomY + 40;
        let prestigeButtonY = prestigeTextY + 50;
        let prestigeButtonWidth = 300;
        let prestigeButtonHeightVal = 60;

    if (mouseXAdjusted >= -prestigeButtonWidth / 2 && mouseXAdjusted <= prestigeButtonWidth / 2 &&
        mouseYAdjusted >= prestigeButtonY - prestigeButtonHeightVal / 2 && mouseYAdjusted <= prestigeButtonY + prestigeButtonHeightVal / 2) {
        let tokensToReceive = floor(skullCoinsSpentThisPrestige / 1000);
        if (tokensToReceive >= prestigeRequirement) {
            availablePrestigeTokens += tokensToReceive;
            skullCoinsSpentThisPrestige = 0;
            skullCoins = 0;
            resetAllShopUpgrades();
            prestigeShakeEffect = false;
            saveGame();
            playButtonClickSound();
            if (prestigeSound) prestigeSound.play(0, 1, fxVolume);
        } else {
            prestigeShakeEffect = true;
            prestigeShakeTimer = millis();
            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume); 
        }
        return;
    }

        for (let row = 0; row < 3; row++) {
            for (let col = 0; col < 3; col++) {
                let itemIndex = row * 3 + col;
                if (itemIndex >= prestigeItems.length) continue;

                let item = prestigeItems[itemIndex];
                let itemCenterX = gridStartX + col * (itemWidth + spacingX);
                let itemCenterY = gridStartY + row * (itemHeight + spacingY);
                let purchaseButtonCenterY = itemCenterY + itemHeight / 2 - 10 - purchaseButtonHeight / 2;
                let purchaseButtonWidthVal = itemWidth - 30;

                if (mouseXAdjusted >= itemCenterX - purchaseButtonWidthVal / 2 && mouseXAdjusted <= itemCenterX + purchaseButtonWidthVal / 2 &&
                    mouseYAdjusted >= purchaseButtonCenterY - purchaseButtonHeight / 2 && mouseYAdjusted <= purchaseButtonCenterY + purchaseButtonHeight / 2) {

                    if (!item.purchased) {
                        if (availablePrestigeTokens >= item.price) {
                            availablePrestigeTokens -= item.price;
                            item.purchased = true;
                            saveGame();
                            playButtonClickSound();
                        } else {
                            prestigeTokenShake = true;
                            prestigeTokenShakeTimer = millis();
                            if (insufficientFundsSound) insufficientFundsSound.play(0, 1, fxVolume);
                        }
                    }
                    return;
                }
            }
        }

    } else if (currentMenu === "options") {
        let adjustedMx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - halfW;
        let adjustedMy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - halfH;
        if (isSliderKnobClicked(adjustedMx, adjustedMy, -50, 'musicVolume')) { draggingMusicSlider = true; return; }
        if (isSliderKnobClicked(adjustedMx, adjustedMy, 30, 'fxVolume')) { draggingFXSlider = true; return; }
        if (isSliderKnobClicked(adjustedMx, adjustedMy, 110, 'mouseSensitivity')) { draggingSensitivitySlider = true; return; }

    } else if (currentMenu === "save") {
        let saveX = -150;
        let resetX = 150;
        let btnY = -50;
        let btnW = 250;
        let btnH = 60;

        if (mouseXAdjusted >= saveX - btnW / 2 && mouseXAdjusted <= saveX + btnW / 2 &&
            mouseYAdjusted >= btnY - btnH / 2 && mouseYAdjusted <= btnY + btnH / 2) {
            if (saveGame()) {
                triggerMessage("Game Data Has Been Saved", color(0, 255, 0));
            } else {
                triggerMessage("Could Not Save Game Data", color(255, 0, 0));
            }
            playButtonClickSound();
            return;
        }

        if (mouseXAdjusted >= resetX - btnW / 2 && mouseXAdjusted <= resetX + btnW / 2 &&
            mouseYAdjusted >= btnY - btnH / 2 && mouseYAdjusted <= btnY + btnH / 2) {
            if (!isHoldingReset) {
                isHoldingReset = true;
                progressResetCompleted = false;
                resetHoldStartTime = millis();
                triggerMessage("", color(255), true);
                playButtonClickSound();
            }
            return;
        }
    }
}

