function isSliderKnobClicked(mx, my, sliderY, type) {
	let sliderX = 0;
	let sliderWidth = 300;
	let sliderLeft = sliderX - sliderWidth / 2;
	let knobY = sliderY + 40;

	let currentValue;

	if (type === 'musicVolume') {
		currentValue = musicVolume;
	} else if (type === 'fxVolume') {
		currentValue = fxVolume;
	} else if (type === 'mouseSensitivity') {
		currentValue = map(mouseSensitivity, 0.001, 0.01, 0, 1);
	}

	let knobX = sliderLeft + currentValue * sliderWidth;
	let knobSize = 20;
	let halfKnobSize = knobSize / 2;

	return (mx >= knobX - halfKnobSize && mx <= knobX + halfKnobSize &&
		my >= knobY - halfKnobSize && my <= knobY + halfKnobSize);
}

