	let sliderWidth = 300;
	let sliderLeft = -sliderWidth / 2;
	let percentage = (mx - sliderLeft) / sliderWidth;
	percentage = constrain(percentage, 0, 1);

	if (type === 'musicVolume') {
		musicVolume = percentage;
		ambientSound.setVolume(musicVolume);
	} else if (type === 'fxVolume') {
		fxVolume = percentage;
		walkingSound.setVolume(fxVolume);
		runningSound.setVolume(fxVolume);
		landingSound1.setVolume(fxVolume);
		landingSound2.setVolume(fxVolume);
		landingSound3.setVolume(fxVolume);
        if (buttonClickSound) buttonClickSound.setVolume(fxVolume);
        if (energyShieldSound) energyShieldSound.setVolume(fxVolume);
        if (iWillBeBackSound) iWillBeBackSound.setVolume(fxVolume);
        if (sonarSound) sonarSound.setVolume(fxVolume);
        if (enemyIsComingSound) enemyIsComingSound.setVolume(fxVolume);
        if (angelWingsSound) angelWingsSound.setVolume(fxVolume);
        if (angelSpawnSound) angelSpawnSound.setVolume(fxVolume); 
		collectCoinSound.setVolume(fxVolume);
        if (slotMachineSpinSound) slotMachineSpinSound.setVolume(fxVolume);
        if (winSound) winSound.setVolume(fxVolume);
        if (coinDropSound) coinDropSound.setVolume(fxVolume);
        if (insufficientFundsSound) insufficientFundsSound.setVolume(fxVolume);
