        if (loseSound) loseSound.setVolume(fxVolume);
        for (let sound of enemyLaughSounds) {
             if (sound) sound.setVolume(fxVolume);
         }

	} else if (type === 'mouseSensitivity') {

		mouseSensitivity = map(percentage, 0, 1, 0.001, 0.01);
	}
}

