class CasinoButton {
    constructor(x, y, w, h, label) {
        this.x = x;
        this.y = y;
        this.width = w;
        this.height = h;
        this.label = label;
        this.isPressed = false;
    }
    contains(px, py) {
         return px > this.x - this.width / 2 && px < this.x + this.width / 2 &&
               py > this.y - this.height / 2 && py < this.y + this.height / 2;
    }
     handlePress(px, py) {
        if (this.contains(px, py)) {
            this.isPressed = true;
             return true;
        }
        return false;
    }
     handleRelease(px, py, boundsRect) {
       let triggered = this.isPressed;
       this.isPressed = false;

       let checkX = px - boundsRect.x + boundsRect.w / 2;
       let checkY = py - boundsRect.y + boundsRect.h / 2;

       return triggered && this.contains(checkX, checkY);
     }
    display(boundsRect) {
        push();
        translate(boundsRect.x - boundsRect.w / 2, boundsRect.y - boundsRect.h / 2);
        rectMode(CENTER);
        noStroke();

        fill(0, 0, 0, 50);
        rect(this.x + 2, this.y + 2, this.width, this.height, 10);

        let checkX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - boundsRect.x + boundsRect.w / 2;
        let checkY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - boundsRect.y + boundsRect.h / 2;

        let hover = this.contains(checkX, checkY);

        fill(this.isPressed && hover ? [180, 30, 30] : hover ? [220, 50, 50] : [200, 40, 40]);
        rect(this.x, this.isPressed && hover ? this.y + 1 : this.y, this.width, this.height, 10);

        fill(255);
        textSize(20);
        textAlign(CENTER, CENTER);
        text(this.label, this.x, this.y);
        pop();
    }
}

class CasinoSlotSymbol {
    constructor(def) {
        this.def = def;
        this.rotation = random(-0.03, 0.03);
    }

    display(x, y, size, blurAmt = 0) {
        if (!this.def) return;
        push();
        translate(x, y);
        rotate(this.rotation);
        let displaySize = size * 0.85; 

        if (this.def.texture && this.def.texture.width > 0 && this.def.texture.height > 0) {
            imageMode(CENTER);
            if (blurAmt > 0) {

            }
            image(this.def.texture, 0, 0, displaySize, displaySize);

        } else {

            this.drawFallbackShape(0, 0, displaySize);

        }
        pop();
    }

    drawFallbackShape(x, y, size) {
        fill(this.def.color || color(128, 0, 128)); 
        noStroke();
        rectMode(CENTER);

        let safeSize = max(1, size); 

        switch (this.def.type) {
            case 'trash':
                ellipse(x, y, safeSize * 0.9, safeSize * 0.7); 
                break;
            case 'tryAgain':
                rect(x, y, safeSize * 0.8, safeSize * 0.8, safeSize * 0.15); 
                break;
            case 'skullCoinSymbol':
                ellipse(x, y, safeSize, safeSize); 
                break;
            case 'redRubySymbol': 
                quad(x, y - safeSize / 2,
                     x + safeSize / 2, y,
                     x, y + safeSize / 2,
                     x - safeSize / 2, y);
                break;
            case 'prestigeTokenSymbol': 
                push();
                translate(x,y);
                let step = TWO_PI / 10;
                let halfStep = step / 2;
                beginShape();
                for (let a = -PI / 2; a < TWO_PI - PI / 2; a += step) {
                    vertex(cos(a) * safeSize / 2, sin(a) * safeSize / 2);
                    vertex(cos(a + halfStep) * safeSize / 4, sin(a + halfStep) * safeSize / 4);
                }
                endShape(CLOSE);
                pop();
                break;

            default:

                fill(100, 100, 100); 
                rect(x, y, safeSize * 0.75, safeSize * 0.75); 
                break;
        }
    }
}

class CasinoReel {
    constructor(x, y, index, symbolSize) {
        this.x = x;
        this.y = y;
        this.index = index;
        this.symbolSize = symbolSize;
        this.reelStrip = [];
        this.visibleSymbols = [];
        this.offset = 0;
        this.speed = 0;
        this.isSpinning = false;
        this.isDecelerating = false;
        this.spinStartTime = 0;
        this.spinDuration = SPIN_TIME_BASE + index * SPIN_TIME_PER_REEL;
        this.targetStopIndex = 0;
        this.targetOffset = 0;
        this.highlightTimer = 0;
        this.totalStripHeight = REEL_STRIP_LENGTH * this.symbolSize;

        this.debug_logicallyChosenSymbolInstance = null;
        this.debug_intendedCenterSymbolInstance = null;

        this.initializeReelStrip();

        if (this.reelStrip.length > 0) {
            this.targetStopIndex = floor(random(this.reelStrip.length));
        } else {
            this.targetStopIndex = 0;
        }
        this.offset = (this.targetStopIndex * this.symbolSize);
        this.targetOffset = this.offset;

        this.initializeVisibleSymbols();
        this.updateVisibleSymbols();
        console.log(`Reel ${this.index} CONSTRUCTOR: Initial targetStopIndex=${this.targetStopIndex}, offset=${this.offset.toFixed(3)}. UVS called.`);
    }

    getCenterSymbolDef() {
        if (!this.visibleSymbols || this.visibleSymbols.length === 0) return null;
        if (!this.isSpinning && !this.isDecelerating) {
            const midCacheIndex = Math.floor(this.visibleSymbols.length / 2);
            if (this.visibleSymbols[midCacheIndex] && this.visibleSymbols[midCacheIndex].symbol) {
                return this.visibleSymbols[midCacheIndex].symbol.def;
            }
        }
        let winning = this.visibleSymbols[0];
        if (!winning || !winning.symbol) return null;
        let smallest = Math.abs(winning.y - this.y);

        for (let i = 1; i < this.visibleSymbols.length; i++) {
            if (!this.visibleSymbols[i] || !this.visibleSymbols[i].symbol) continue;
            const d = Math.abs(this.visibleSymbols[i].y - this.y);
            if (d < smallest) {
                winning = this.visibleSymbols[i];
                smallest = d;
            }
        }
        return winning && winning.symbol ? winning.symbol.def : null;
    }

    initializeReelStrip() {
        this.reelStrip = [];
        if (!casinoSymbolDefinitions?.length) {
            for (let i = 0; i < REEL_STRIP_LENGTH; i++) this.reelStrip.push(new CasinoSlotSymbol({ type: 'placeholder', name: 'PH', color: color(100), weight: 1, id: -1, payout: 0, texture: null }));
            return;
        }
        for (let i = 0; i < REEL_STRIP_LENGTH; i++) this.reelStrip.push(new CasinoSlotSymbol(this.getRandomSymbolDef()));
    }

    initializeVisibleSymbols() {
        this.visibleSymbols = [];
        let numToCache = SYMBOLS_PER_REEL_VISIBLE + 2;
        for (let i = 0; i < numToCache; i++) this.visibleSymbols.push({ symbol: null, y: 0 });
    }

    getRandomSymbolDef() {
        if (!casinoSymbolDefinitions?.length) return { type: 'error', name: 'ErrorSym', color: color(255, 0, 0), weight: 1, id: -1, payout: 0, texture: null };
        let totalWeight = casinoSymbolDefinitions.reduce((s, d) => s + (d.weight || 0), 0);
        if (totalWeight <= 0) return casinoSymbolDefinitions[0];
        let rnd = random() * totalWeight, accum = 0;
        for (let d of casinoSymbolDefinitions) {
            accum += (d.weight || 0);
            if (rnd <= accum) return d;
        }
        return casinoSymbolDefinitions[0];
    }

    startSpin(targetIndex) {

        if (targetIndex === undefined || targetIndex === null || targetIndex < 0 || targetIndex >= this.reelStrip.length) {
            console.warn(`Reel ${this.index} STARTSPIN: Received invalid targetIndex ${targetIndex}. Defaulting to random.`);
            this.targetStopIndex = floor(random(this.reelStrip.length));
        } else {
            this.targetStopIndex = targetIndex;
        }

        let expectedSymbolName = "UNKNOWN_SYMBOL";
        if (this.reelStrip[this.targetStopIndex] && this.reelStrip[this.targetStopIndex].def) {
            expectedSymbolName = this.reelStrip[this.targetStopIndex].def.name;
        }
        console.log(`Reel ${this.index} STARTSPIN: Original targetIndex=${targetIndex}, Resolved targetStopIndex=${this.targetStopIndex} (should be '${expectedSymbolName}').`);

        this.targetOffset = (this.targetStopIndex * this.symbolSize);
        while (this.targetOffset < 0) this.targetOffset += this.totalStripHeight;
        this.targetOffset %= this.totalStripHeight;
        console.log(`   targetOffset calculated: ${this.targetOffset.toFixed(3)}`);

        this.isSpinning = true;
        this.isDecelerating = false;
        this.speed = SPIN_SPEED_START + random(-5, 5);
        this.spinStartTime = millis();
        this.highlightTimer = 0;
        this.debug_intendedCenterSymbolInstance = null;
        this.debug_logicallyChosenSymbolInstance = null;
    }

    update() {
        if (!this.isSpinning && !this.isDecelerating) {
            return;
        }

        let currentDeltaTime = deltaTime;
        if (currentDeltaTime <= 0) {
            currentDeltaTime = 16.6667;
        }
        let deltaFactor = currentDeltaTime / 16.6667;

        if (!this.isDecelerating) {
            this.offset = (this.offset + this.speed * deltaFactor + this.totalStripHeight) % this.totalStripHeight;
            if (millis() - this.spinStartTime >= this.spinDuration) {
                this.isDecelerating = true;
            }
            this.updateVisibleSymbols();
        } else {
            let currentOffsetNormalized = (this.offset % this.totalStripHeight + this.totalStripHeight) % this.totalStripHeight;
            let targetOffsetNormalized = (this.targetOffset % this.totalStripHeight + this.totalStripHeight) % this.totalStripHeight;
            let distanceToTarget = targetOffsetNormalized - currentOffsetNormalized;

            if (abs(distanceToTarget) > this.totalStripHeight / 2) {
                if (distanceToTarget > 0) distanceToTarget -= this.totalStripHeight;
                else distanceToTarget += this.totalStripHeight;
            }

            if (abs(distanceToTarget) < MIN_SPEED * deltaFactor * 1.5 && this.speed < MIN_SPEED * 2) {
                let snappedIdx = Math.round(this.targetOffset / this.symbolSize);
                snappedIdx = ((snappedIdx % REEL_STRIP_LENGTH) + REEL_STRIP_LENGTH) % REEL_STRIP_LENGTH;

                this.targetStopIndex = snappedIdx;
                this.offset = this.targetStopIndex * this.symbolSize;
                this.speed = 0;
                this.isSpinning = false;
                this.isDecelerating = false;

                let symbolAtSnap = "ERROR_ACCESSING_REELSTRIP";
                if (this.reelStrip && this.reelStrip[this.targetStopIndex] && this.reelStrip[this.targetStopIndex].def) {
                    symbolAtSnap = this.reelStrip[this.targetStopIndex].def.name;
                }
                console.log(`Reel ${this.index} UPDATE: Snapped to Stop. targetStopIndex=${this.targetStopIndex} (Symbol: '${symbolAtSnap}'), final offset=${this.offset.toFixed(3)}`);
                this.updateVisibleSymbols();
            } else {
                let idealSpeed = abs(distanceToTarget) * DECELERATION_FACTOR;
                this.speed = lerp(this.speed, max(MIN_SPEED, idealSpeed), 0.1 * deltaFactor);
                this.speed = min(this.speed, abs(distanceToTarget) / deltaFactor);

                let moveAmount = this.speed * deltaFactor * Math.sign(distanceToTarget);
                this.offset = (this.offset + moveAmount + this.totalStripHeight) % this.totalStripHeight;
                this.updateVisibleSymbols();
            }
        }

        if (this.highlightTimer > 0) {
            this.highlightTimer -= currentDeltaTime;
            if (this.highlightTimer < 0) this.highlightTimer = 0;
        }
    }

    updateVisibleSymbols() {
        if (!this.reelStrip || this.reelStrip.length === 0) {
            console.error(`Reel ${this.index} UVS: No reelStrip!`);
            return;
        }

        const cacheLen = this.visibleSymbols.length;
        const midCacheIndex = Math.floor(cacheLen / 2);
        const stripSize = REEL_STRIP_LENGTH;

        let currentFineOffset = 0;
        let logOutput = `Reel ${this.index} UVS`;

        if (this.isSpinning || this.isDecelerating) {
            this.debug_intendedCenterSymbolInstance = null;
            const currentBaseOffset = ((this.offset % this.totalStripHeight) + this.totalStripHeight) % this.totalStripHeight;
            currentFineOffset = currentBaseOffset % this.symbolSize;

            for (let i = 0; i < cacheLen; i++) {
                const floatStripIndex = (currentBaseOffset / this.symbolSize) + (i - midCacheIndex);
                let actualStripIndex = (Math.round(floatStripIndex) % stripSize + stripSize) % stripSize;

                this.visibleSymbols[i].symbol = this.reelStrip[actualStripIndex];
                this.visibleSymbols[i].y = this.y + (i - midCacheIndex) * this.symbolSize - currentFineOffset;
            }
        } else {
            currentFineOffset = 0;
            logOutput += ` (IDLE/STOPPED): targetStopIndex=${this.targetStopIndex}, offset=${this.offset.toFixed(3)}. Cache:\n`;

            for (let i = 0; i < cacheLen; i++) {
                let stripIdxForThisCacheSlot = (this.targetStopIndex + (i - midCacheIndex) + stripSize) % stripSize;

                this.visibleSymbols[i].symbol = this.reelStrip[stripIdxForThisCacheSlot];
                this.visibleSymbols[i].y = this.y + (i - midCacheIndex) * this.symbolSize;

                if (i === midCacheIndex) {
                    this.debug_intendedCenterSymbolInstance = this.visibleSymbols[i].symbol;
                }
            }
            if (this.debug_intendedCenterSymbolInstance && this.debug_intendedCenterSymbolInstance.def) {
                logOutput += `  debug_intendedCenterSymbolInstance set to '${this.debug_intendedCenterSymbolInstance.def.name}'\n`;
                console.log(logOutput.trim());
            } else {
                logOutput += `  ERROR: debug_intendedCenterSymbolInstance NOT SET or .def is missing for midCacheIndex ${midCacheIndex}\n`;
                console.error(logOutput.trim());
            }
        }
    }

    highlightCenter() { this.highlightTimer = 1500; }

    getFinalSymbolDef() {
        if (this.isSpinning) { return null; }
        const idx = ((this.targetStopIndex % REEL_STRIP_LENGTH) + REEL_STRIP_LENGTH) % REEL_STRIP_LENGTH;
        return this.reelStrip[idx].def;
    }

    display() {
        push();
        let blurAmount = (this.isSpinning && this.speed > MIN_SPEED * 1.5) ? this.speed * BLUR_FACTOR : 0;

        const maskTopY = this.y - (this.symbolSize * SYMBOLS_PER_REEL_VISIBLE / 2);
        const maskBottomY = this.y + (this.symbolSize * SYMBOLS_PER_REEL_VISIBLE / 2);

        for (let i = 0; i < this.visibleSymbols.length; i++) {
            let vs = this.visibleSymbols[i];
            if (vs.symbol && typeof vs.y === 'number' && vs.symbol.def) {

                if (vs.y > maskTopY - this.symbolSize && vs.y < maskBottomY + this.symbolSize) {

                    if (vs.symbol === this.debug_logicallyChosenSymbolInstance && this.highlightTimer > 0 && !this.isSpinning) {
                        push();
                        fill(255, 255, 0, map(sin(millis() * 0.01), -1, 1, 30, 100));
                        noStroke();
                        ellipse(this.x, vs.y, this.symbolSize * 1.1, this.symbolSize * 1.1);
                        pop();
                    }

                    vs.symbol.display(this.x, vs.y, this.symbolSize, blurAmount);

                }
            }
        }
        pop();
    }

    getPaylineSymbolDef() {
        this.debug_logicallyChosenSymbolInstance = null;
        let return_def = null;

        if (!this.visibleSymbols || this.visibleSymbols.length === 0) {
            console.error(`Reel ${this.index} GPDS: No visibleSymbols array or it's empty.`);
            return null;
        }

        const midCacheIndex = Math.floor(this.visibleSymbols.length / 2);
        let chosenEntry = null;
        let chosenMethod = "";

        if (!this.isSpinning && !this.isDecelerating) {
            chosenEntry = this.visibleSymbols[midCacheIndex];
            chosenMethod = "Direct Mid-Cache (Stopped)";
            if (chosenEntry && chosenEntry.symbol && chosenEntry.symbol.def) {

            } else {
                console.warn(`Reel ${this.index} GPDS (Stopped): Mid-cache entry, symbol, or def is invalid. Falling back. Entry:`, chosenEntry);
                chosenEntry = null;
            }
        }

        if (!chosenEntry) {
            chosenMethod = chosenEntry ? chosenMethod : "Closest-Y (Moving or Fallback)";
            if (!this.visibleSymbols[0] || !this.visibleSymbols[0].symbol) {
                console.error(`Reel ${this.index} GPDS (${chosenMethod}): visibleSymbols[0] or its symbol is invalid.`);
                return null;
            }
            chosenEntry = this.visibleSymbols[0];
            let bestDiff = Math.abs(chosenEntry.y - this.y);

            for (let i = 1; i < this.visibleSymbols.length; i++) {
                const currentEntry = this.visibleSymbols[i];
                if (!currentEntry || !currentEntry.symbol || !currentEntry.symbol.def) {
                    console.warn(`Reel ${this.index} GPDS (${chosenMethod}): Skipping invalid entry in visibleSymbols at index ${i}`);
                    continue;
                }
                const diff = Math.abs(currentEntry.y - this.y);
                if (diff < bestDiff) {
                    bestDiff = diff;
                    chosenEntry = currentEntry;
                }
            }
        }

        if (chosenEntry && chosenEntry.symbol && chosenEntry.symbol.def) {
            this.debug_logicallyChosenSymbolInstance = chosenEntry.symbol;
            return_def = chosenEntry.symbol.def;

            console.log(`Reel ${this.index} GPDS: Method='${chosenMethod}'. Final Choice='${return_def.name}', Y=${chosenEntry.y.toFixed(3)}.`);
            return return_def;
        } else {
            console.error(`Reel ${this.index} GPDS: Could not determine a valid chosenEntry or its symbol/def. ChosenMethod: '${chosenMethod}', ChosenEntry:`, chosenEntry);
            return null;
        }
    }
}

function checkCasinoWinningCombinations() {
    if (!casinoReels || casinoReels.length !== REELS || !casinoReels.every(r => r && !r.isSpinning && !r.isDecelerating)) {
        console.warn("CWC: Bailing early - reels not ready, not all stopped, or casinoSpinning might be false prematurely.");
        return;
    }

    console.log("--- CWC START --- TS: " + millis() + " ---");

    let finalSymbolDefsForLogic = [];
    let collectedNamesForDisplay = ["- ERROR -", "- ERROR -", "- ERROR -"];
    let symbolReadError = false;

    console.log("CWC: About to collect symbol definitions from reels.");

    for (let i = 0; i < REELS; i++) {
        console.log(`CWC: Processing Reel ${i}`);
        const currentReelInstance = casinoReels[i];
        if (!currentReelInstance) {
            symbolReadError = true;
            console.error(`CWC: Reel ${i} instance IS MISSING!`);
            break;
        }

        console.log(`CWC: Reel ${i}: Calling getPaylineSymbolDef().`);
        const definitionFromReel = currentReelInstance.getPaylineSymbolDef();

        if (!definitionFromReel) {
            symbolReadError = true;
            console.error(`CWC: Reel ${i}: getPaylineSymbolDef() RETURNED NULL/FALSY.`);
            collectedNamesForDisplay[i] = "SYM_READ_ERR";
            break;
        }

        console.log(`CWC: Reel ${i}: GOT definition: ${definitionFromReel.name} (Type: ${definitionFromReel.type}). Pushing to finalSymbolDefsForLogic.`);
        collectedNamesForDisplay[i] = definitionFromReel.name || "Unnamed";
        finalSymbolDefsForLogic.push(definitionFromReel);
        console.log(`CWC: Reel ${i}: finalSymbolDefsForLogic length is now ${finalSymbolDefsForLogic.length}`);
    }

    casinoLastSpinResultNames = [...collectedNamesForDisplay];

    if (symbolReadError || finalSymbolDefsForLogic.length !== REELS) {
        casinoLastWin = "Error Reading Reels";
        console.error(`CWC: ERROR STATE. Symbol read error: ${symbolReadError}, finalSymbolDefsForLogic length: ${finalSymbolDefsForLogic.length}. Expected ${REELS} symbols.`);
        console.log("--- CWC END (Read Error / Incomplete Payline) ---");
        casinoSpinning = false;
        casinoResultPending = false;
        if (slotMachineSpinSound && slotMachineSpinSound.isLooping()) {
            slotMachineSpinSound.stop();
        }
        console.log("CWC: casinoSpinning = false, casinoResultPending = false (due to error/incomplete payline)");
        return;
    }

    console.log("CWC: SUCCESSFULLY COLLECTED Symbols on payline for logic:", finalSymbolDefsForLogic.map(s => s ? s.name : "NULL_DEF_IN_ARRAY"));

    let symbolCounts = {};
    finalSymbolDefsForLogic.forEach(d => {
        if (d && d.type) {
            symbolCounts[d.type] = (symbolCounts[d.type] || 0) + 1;
        } else {
            console.warn("CWC: Encountered an undefined/null symbol definition in finalSymbolDefsForLogic during counting:", d);
        }
    });

    let winMessages = [];
    let skullCoinWinThisSpin = 0;
    let prestigeTokenWinThisSpin = 0;
    let casinoCoinWinThisSpin = 0;
    let reelsToHighlight = new Set();
    let valuableWinOccurred = false;

    for (const type in symbolCounts) {
        const count = symbolCounts[type];
        if (count === 3) {
            console.log(`CWC: Matched 3 of type '${type}'`);
            reelsToHighlight.add(0); reelsToHighlight.add(1); reelsToHighlight.add(2);
            if (type === 'tryAgain') {
                let coinsNeededToFill = Math.max(0, MAX_CASINO_SKULL_COINS - casinoSkullCoinsBalance);
                casinoCoinWinThisSpin += coinsNeededToFill;
                if (coinsNeededToFill > 0) {
                     winMessages.push('TANK FILLED!');
                } else {
                     winMessages.push('TANK FULL!');
                }
            } else if (type === 'skullCoinSymbol') {
                skullCoinWinThisSpin += 1500;
            } else if (type === 'redRubySymbol') {
                skullCoinWinThisSpin += 100000;
            } else if (type === 'prestigeTokenSymbol') {
                prestigeTokenWinThisSpin += 200;
            }
        } else if (count === 2) {
            console.log(`CWC: Matched 2 of type '${type}' (Any Position Check)`);

            let matchingIndices = [];
            for(let i=0; i < finalSymbolDefsForLogic.length; i++){
                 if(finalSymbolDefsForLogic[i].type === type) {
                     matchingIndices.push(i);
                 }
            }

            if (type === 'tryAgain') {
                casinoCoinWinThisSpin += 1;
                 if (!winMessages.some(msg => msg.includes('FREE SPIN') || msg.includes('TANK'))) {
                     winMessages.push('1 FREE SPIN');
                     matchingIndices.forEach(idx => reelsToHighlight.add(idx));
                 }
            } else if (type === 'skullCoinSymbol') {
                skullCoinWinThisSpin += 300;
                matchingIndices.forEach(idx => reelsToHighlight.add(idx));
            } else if (type === 'redRubySymbol') {
                skullCoinWinThisSpin += 15000;
                matchingIndices.forEach(idx => reelsToHighlight.add(idx));
            } else if (type === 'prestigeTokenSymbol') {
                prestigeTokenWinThisSpin += 25;
                matchingIndices.forEach(idx => reelsToHighlight.add(idx));
            }
        }
    }

    if (skullCoinWinThisSpin > 0) {
        skullCoins += skullCoinWinThisSpin;
        skullCoins = Math.min(skullCoins, maxSkullCoins);
        if (!winMessages.some(msg => msg.includes('SKULLS'))) {
             winMessages.push(`${nfc(skullCoinWinThisSpin)} SKULLS`);
        }
        console.log(`CWC: Awarded ${skullCoinWinThisSpin} Skull Coins. New total: ${skullCoins}`);
        valuableWinOccurred = true;
    }
    if (prestigeTokenWinThisSpin > 0) {
        availablePrestigeTokens += prestigeTokenWinThisSpin;
         if (!winMessages.some(msg => msg.includes('PRESTIGE'))) {
             winMessages.push(`${nfc(prestigeTokenWinThisSpin)} PRESTIGE`);
         }
        console.log(`CWC: Awarded ${prestigeTokenWinThisSpin} Prestige Tokens. New total: ${availablePrestigeTokens}`);
        valuableWinOccurred = true;
    }
    if (casinoCoinWinThisSpin > 0) {
        let initialBalance = casinoSkullCoinsBalance;
        casinoSkullCoinsBalance += casinoCoinWinThisSpin;
        casinoSkullCoinsBalance = Math.min(casinoSkullCoinsBalance, MAX_CASINO_SKULL_COINS);
        let actualCoinsAwarded = casinoSkullCoinsBalance - initialBalance;

        if (actualCoinsAwarded > 0) {
             console.log(`CWC: Awarding ${actualCoinsAwarded} Casino Coins (Free Spins / Tank Fill). New total: ${casinoSkullCoinsBalance}`);
             for (let k = 0; k < actualCoinsAwarded; k++) {
                 if (fallingCasinoCoins.length < MAX_CASINO_SKULL_COINS) {
                    fallingCasinoCoins.push({
                        x: currentCasinoLayout.coinDropZone.x + random(-currentCasinoLayout.coinDropZone.w * 0.2, currentCasinoLayout.coinDropZone.w * 0.2),
                        y: currentCasinoLayout.coinDropZone.y - currentCasinoLayout.coinDropZone.h / 2 - casinoCoinSize,
                        targetY: 0,
                        hasLandedSoundPlayed: false
                    });
                 }
             }
             valuableWinOccurred = true;
        } else {
            console.log(`CWC: Tank was already full or no coins needed for 2xTryAgain. Balance remains ${casinoSkullCoinsBalance}.`);
            if (!winMessages.includes('TANK FULL!')) {
                 winMessages = winMessages.filter(msg => !msg.includes('FREE SPIN'));
                 if (symbolCounts['tryAgain'] === 3) {
                     if (!winMessages.includes('TANK FULL!')) winMessages.push('TANK FULL!');
                 }
            }
        }
    }

    if (valuableWinOccurred && winSound) {
        winSound.play(0, 1, fxVolume);
    }

    if (winMessages.length > 0) {
        winMessages = winMessages.filter((item, index) => winMessages.indexOf(item) === index);
        casinoLastWin = winMessages.join(' & ');

        reelsToHighlight.forEach(reelIndex => {
            if (casinoReels[reelIndex]) {
                 console.log(`CWC: Highlighting reel ${reelIndex}`);
                 casinoReels[reelIndex].highlightTimer = 1500;
            }
        });

    } else {
        casinoLastWin = "";
        console.log("CWC: No specific win messages generated for display (casinoLastWin set to empty string).");
    }

    console.log(`CWC: Final casinoLastWin message: "${casinoLastWin}"`);
    console.log("--- CWC END (Normal) ---");

    casinoSpinning = false;
    casinoResultPending = false;
    if (slotMachineSpinSound && slotMachineSpinSound.isLooping()) {
        slotMachineSpinSound.stop();
    }
    console.log("CWC: casinoSpinning = false, casinoResultPending = false (end of CWC)");
}

function setupCasinoReels(boundsRect) {

    casinoReels = [];

    const symbolSize = max(
        10,
        min(boundsRect.w / REELS,
            boundsRect.h / SYMBOLS_PER_REEL_VISIBLE)
    ) * 0.95;

    const totalWidth = (symbolSize * REELS) + (REEL_SPACING * (REELS - 1));
    const startX     = boundsRect.x - totalWidth / 2 + symbolSize / 2;
    const centreY    = boundsRect.y;

    for (let i = 0; i < REELS; i++) {
        const reelX = startX + i * (symbolSize + REEL_SPACING);
        casinoReels.push(new CasinoReel(reelX, centreY, i, symbolSize));
    }
}

