function drawCasinoLogic(reelsLayoutRect, clipAreaRect) {
    if (!casinoInitialized) setupCasinoLogic();

    const gl = _renderer.GL;
    gl.enable(gl.SCISSOR_TEST);
    gl.scissor(
        floor((clipAreaRect.x - clipAreaRect.w / 2 + width / 2) * pixelDensity()),
        floor((height - ((clipAreaRect.y + clipAreaRect.h / 2) + height / 2)) * pixelDensity()),
        floor(clipAreaRect.w * pixelDensity()),
        floor(clipAreaRect.h * pixelDensity())
    );
    push();
    rectMode(CENTER);
