        (casinoReels.length && abs(casinoReels[0].symbolSize - symSize) > 1);
    const reelStillVisiblyMoving = casinoReels.some(r => r && (r.isSpinning || r.isDecelerating));

    if (setupNeeded && !reelStillVisiblyMoving) {
         setupCasinoReels(reelsLayoutRect);
    }

    if (REELS > 1 && casinoReels.length === REELS && casinoReels[0] && casinoReels[1]) {
        push();
        stroke(0);
        strokeWeight(4);

        const lineTopY = clipAreaRect.y - clipAreaRect.h / 2;
        const lineBottomY = clipAreaRect.y + clipAreaRect.h / 2;

        if (REELS >= 2) {
            const line1X = (casinoReels[0].x + casinoReels[1].x) / 2;
            line(line1X, lineTopY, line1X, lineBottomY);
        }
        if (REELS >= 3 && casinoReels[2]) {
            const line2X = (casinoReels[1].x + casinoReels[2].x) / 2;
            line(line2X, lineTopY, line2X, lineBottomY);
        }
        pop();
    }

    casinoReels.forEach(r => { r.update(); r.display(); });

    gl.disable(gl.SCISSOR_TEST);

    const allReelsLogicallyStopped = casinoReels.every(r => r && !r.isSpinning && !r.isDecelerating);
    const anyReelWasSpinningThisCycle = casinoReels.some(r => r && r.spinStartTime > 0 && casinoSpinning);

    if (allReelsLogicallyStopped && anyReelWasSpinningThisCycle && !casinoResultPending) {

        casinoResultPending = true;
        console.log("DRAW_CASINO_LOGIC: All reels stopped, casinoResultPending = true. Calling CWC.");
        checkCasinoWinningCombinations();

    }

