function determineCasinoTargetIndexes() {
    let targetIndexes = [];
    let initialReelStripSymbolsAtChosenIndexes = ["-", "-", "-"];

    console.log("DCTI: --- DetermineCasinoTargetIndexes START ---");

    for (let i = 0; i < REELS; i++) {
        if (casinoReels[i] && casinoReels[i].reelStrip.length > 0) {
            targetIndexes.push(floor(random(casinoReels[i].reelStrip.length)));
        } else {
            targetIndexes.push(0);
            console.warn(`DCTI: Reel ${i} or its reelStrip is invalid, defaulting targetIndex to 0.`);
        }
    }
    console.log("DCTI: Initial random targetIndexes chosen:", JSON.parse(JSON.stringify(targetIndexes)));

    for (let i = 0; i < REELS; i++) {
        if (casinoReels[i] && casinoReels[i].reelStrip[targetIndexes[i]] && casinoReels[i].reelStrip[targetIndexes[i]].def) {
            initialReelStripSymbolsAtChosenIndexes[i] = casinoReels[i].reelStrip[targetIndexes[i]].def.name;
        } else {
            initialReelStripSymbolsAtChosenIndexes[i] = "REELSTRIP_ERR";
            console.warn(`DCTI: Error accessing reelStrip symbol for Reel ${i} at initial targetIndex ${targetIndexes[i]}`);
        }
    }
    console.log("DCTI: Symbols on reelStrips at initially chosen random targetIndexes:", JSON.parse(JSON.stringify(initialReelStripSymbolsAtChosenIndexes)));

    let forceWin = PLAYER_ADVANTAGE && random() < WIN_RATE && casinoInitialized;

    if (forceWin) {
        console.log("DCTI: Forcing a win (5% chance).");
        let isJackpot = random() < JACKPOT_ODDS; 
        let winSymbolDefToForce = null;
        let winLength = REELS; 

        console.log("DCTI: Jackpot attempt for forced win:", isJackpot);
        let potentialWinDefs = casinoSymbolDefinitions.filter(d => (d.payout && d.payout > 0) || d.type === 'tryAgain' || d.type === 'prestigeTokenSymbol');

        if (potentialWinDefs.length > 0) {
            if (isJackpot) {
                winSymbolDefToForce = potentialWinDefs.reduce((highest, current) => {
                    let currentPayoutVal = current.payout || (current.type === 'prestigeTokenSymbol' ? 100 : (current.type === 'tryAgain' ? 1 : 0));
                    let highestPayoutVal = highest.payout || (highest.type === 'prestigeTokenSymbol' ? 100 : (current.type === 'tryAgain' ? 1 : 0));
                    return currentPayoutVal > highestPayoutVal ? current : highest;
                }, potentialWinDefs[0]);
                console.log("DCTI: Jackpot win forced with symbol:", winSymbolDefToForce ? winSymbolDefToForce.name : "None");
            } else {
                winSymbolDefToForce = potentialWinDefs[floor(random(potentialWinDefs.length))];
                console.log("DCTI: Regular win forced with symbol:", winSymbolDefToForce ? winSymbolDefToForce.name : "None");
            }
        } else {
            console.log("DCTI: Wanted to force win, but no potential winning symbols found. Falling back to random.");
            forceWin = false; 
        }

        if (forceWin && winSymbolDefToForce) { 
            console.log(`DCTI: Applying forced win symbol '${winSymbolDefToForce.name}' to ${winLength} reel(s).`);
            for (let i = 0; i < winLength; i++) {
                if (casinoReels[i] && casinoReels[i].reelStrip[targetIndexes[i]]) { 
                    if (targetIndexes[i] >= 0 && targetIndexes[i] < casinoReels[i].reelStrip.length) {
                        console.log(`DCTI: Reel ${i}: Overwriting reelStrip[${targetIndexes[i]}] (was '${initialReelStripSymbolsAtChosenIndexes[i]}') with '${winSymbolDefToForce.name}'.`);

                        casinoReels[i].reelStrip[targetIndexes[i]] = new CasinoSlotSymbol(winSymbolDefToForce);
                    } else {
                        console.error(`DCTI: Reel ${i}: Invalid targetIndex ${targetIndexes[i]} during force. Cannot overwrite.`);
                    }
                } else {
                    console.error(`DCTI: Reel ${i} or its reelStrip or symbol at targetIndex ${targetIndexes[i]} is invalid during force.`);
                }
            }

        }

    } else {
        console.log("DCTI: Not forcing a win this spin (95% chance or failed to find win symbol). Using purely random targets.");

    }

    let finalSymbolsForLog = ["-", "-", "-"];
    for (let i = 0; i < REELS; i++) {
        if (casinoReels[i] && casinoReels[i].reelStrip[targetIndexes[i]] && casinoReels[i].reelStrip[targetIndexes[i]].def) {
            finalSymbolsForLog[i] = casinoReels[i].reelStrip[targetIndexes[i]].def.name;
        } else {
            finalSymbolsForLog[i] = "REELSTRIP_ERR_FINAL";
            console.warn(`DCTI: Error accessing reelStrip symbol for Reel ${i} at FINAL targetIndex ${targetIndexes[i]}`);
        }
    }
    console.log("DCTI: Symbols on reelStrips that WILL BE TARGETED (after any forcing):", JSON.parse(JSON.stringify(finalSymbolsForLog)));
    console.log("DCTI: Final targetIndexes being returned:", JSON.parse(JSON.stringify(targetIndexes)));
    console.log("DCTI: --- DetermineCasinoTargetIndexes END ---");
    return targetIndexes;
}

function startCasinoSpinSequence() {
    if (casinoReels.some(r => r && (r.isSpinning || r.isDecelerating))) {
        console.log("START_CASINO_SPIN: Cannot start, reels already moving.");
        return;
    }

    casinoSpinning = true;
    console.log("START_CASINO_SPIN: casinoSpinning = true");

    casinoLastWin = "";
    casinoResultPending = false;

    console.log("START_CASINO_SPIN: Re-initializing reel strips based on weights.");
    if (casinoReels && casinoReels.length === REELS) {
         casinoReels.forEach(reel => {
             if(reel) {
                 reel.initializeReelStrip();
                 reel.updateVisibleSymbols();
             } else {
                 console.error("START_CASINO_SPIN: Found invalid reel during re-initialization!");
             }
         });
    } else {
         console.error("START_CASINO_SPIN: casinoReels array is not set up correctly for re-initialization!");
         casinoSpinning = false;
         return;
    }

    const targetIndexes = determineCasinoTargetIndexes();

    const r0 = casinoReels[0];
    if (r0 && r0.reelStrip.length > 0) {
        r0.startSpin(targetIndexes[0] % r0.reelStrip.length);
    } else {
        console.error("START_CASINO_SPIN: Reel 0 or its strip is invalid!");
        casinoSpinning = false;
        return;
    }

    for (let i = 1; i < REELS; i++) {
        const reel = casinoReels[i];
        if (reel && reel.reelStrip.length > 0) {
            const t = targetIndexes[i] % reel.reelStrip.length;
            setTimeout(() => {
                if (reel) reel.startSpin(t);
            }, i * 100);
        } else {
            console.error(`START_CASINO_SPIN: Reel ${i} or its strip is invalid!`);
        }
    }

    if (slotMachineSpinSound && !slotMachineSpinSound.isLooping()) {
        slotMachineSpinSound.loop(0, 1, fxVolume);
    }
}

