function calculateCasinoLayout(currentWidth, currentHeight) {
    let layout = {
        machine: {},
        tank: {},
        panel: {},
        reelsClipMask: {},
        reelsBounds: {},
        coinDropZone: {},
        infoPanel: {},
        buttons: {
            buyCoin: {},
            spin: {}
        }
    };

    const aspectRatioMachine = (slotMachineImage && slotMachineImage.width > 0 && slotMachineImage.height > 0) ? slotMachineImage.width / slotMachineImage.height : 0.7;
    const aspectRatioTank = (coinTankImage && coinTankImage.width > 0 && coinTankImage.height > 0) ? coinTankImage.width / coinTankImage.height : 0.3;
    const aspectRatioPanel = (casinoPanelImage && casinoPanelImage.width > 0 && casinoPanelImage.height > 0) ? casinoPanelImage.width / casinoPanelImage.height : 0.3;

    layout.machine.h = currentHeight * 0.6 * 1.4;
    layout.machine.w = layout.machine.h * aspectRatioMachine;

    const maxMachineWidth = currentWidth * 0.40;
    if (layout.machine.w > maxMachineWidth) {
        layout.machine.w = maxMachineWidth;
        layout.machine.h = layout.machine.w / aspectRatioMachine;
    }

    layout.machine.x = 0;
    layout.machine.y = 0 + currentHeight * 0.08; 

    const sideImageHeightFactor = 0.8;
    layout.tank.h = layout.machine.h * sideImageHeightFactor;
    layout.tank.w = layout.tank.h * aspectRatioTank;
    layout.tank.x = layout.machine.x - layout.machine.w / 2 - layout.tank.w / 2 - currentWidth * 0.02;
    layout.tank.y = layout.machine.y;

    layout.panel.h = layout.machine.h * sideImageHeightFactor;
    layout.panel.w = layout.panel.h * aspectRatioPanel;
    layout.panel.x = layout.machine.x + layout.machine.w / 2 + layout.panel.w / 2 + currentWidth * 0.02;
    layout.panel.y = layout.machine.y;

    const totalReelWindowHorizontalFactorFromMachineCenter = -0.001; 

    layout.reelsClipMask.w = layout.machine.w * 0.67;
    layout.reelsClipMask.h = layout.machine.h * 0.27;

    layout.reelsClipMask.x = layout.machine.x + (layout.machine.w * totalReelWindowHorizontalFactorFromMachineCenter);
    layout.reelsClipMask.y = layout.machine.y - layout.machine.h * 0.038 + layout.machine.h * 0.06;

    layout.reelsBounds.w = layout.machine.w * 0.51;
    layout.reelsBounds.h = layout.machine.h * 0.25;

    layout.reelsBounds.x = layout.machine.x + (layout.machine.w * totalReelWindowHorizontalFactorFromMachineCenter);
    layout.reelsBounds.y = layout.reelsClipMask.y; 

    layout.coinDropZone.w = layout.tank.w * 0.15;
    layout.coinDropZone.h = layout.tank.h * 0.46;
    layout.coinDropZone.x = layout.tank.x - layout.tank.w * 0.06;
    layout.coinDropZone.y = layout.tank.y + layout.tank.h * 0.11;

    layout.infoPanel.w = layout.panel.w * 0.67;
    layout.infoPanel.h = layout.panel.h * 0.24;
    layout.infoPanel.x = layout.panel.x;
    layout.infoPanel.y = layout.panel.y - layout.panel.h * 0.09;

    layout.buttons.buyCoin.w = layout.panel.w * 0.35;
    layout.buttons.buyCoin.h = layout.panel.h * 0.14;
    layout.buttons.buyCoin.x = layout.panel.x - layout.panel.w * 0.23;
    layout.buttons.buyCoin.y = layout.panel.y + layout.panel.h * 0.17;

    layout.buttons.spin.w = layout.panel.w * 0.35;
    layout.buttons.spin.h = layout.panel.h * 0.14;
    layout.buttons.spin.x = layout.panel.x + layout.panel.w * 0.23;
    layout.buttons.spin.y = layout.panel.y + layout.panel.h * 0.17;

    return layout;
}

const dissolveVertShaderSrc = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal; 

varying vec2 vTexCoord;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
}
`;

const dissolveFragShaderSrc = `
precision highp float;

varying vec2 vTexCoord;

uniform sampler2D uWallTexture;
uniform sampler2D uNoiseTexture;
uniform float uDissolveThreshold; 
uniform vec3 uEdgeColor;         
uniform float uTime;             

void main() {
  vec4 wallColor = texture2D(uWallTexture, vTexCoord);

  float noiseCoordOffset = sin(uTime * 2.0 + vTexCoord.y * 10.0) * 0.01;
  float noiseValue = texture2D(uNoiseTexture, vTexCoord + noiseCoordOffset).r;

  float edgeWidth = 0.15; 
  float fadeWidth = 0.1;  

  float dissolveFactor = smoothstep(uDissolveThreshold - fadeWidth, uDissolveThreshold + edgeWidth, noiseValue);

  float edgeIntensity = smoothstep(uDissolveThreshold - edgeWidth * 0.5, uDissolveThreshold, noiseValue) *
                        (1.0 - smoothstep(uDissolveThreshold, uDissolveThreshold + edgeWidth * 1.5, noiseValue));

  edgeIntensity *= (0.8 + sin(uTime * 10.0 + noiseValue * 5.0) * 0.2);
  edgeIntensity = max(0.0, edgeIntensity); 

  vec3 finalColor = wallColor.rgb + uEdgeColor * edgeIntensity * 2.5; 

  float finalAlpha = wallColor.a * dissolveFactor;

  if (finalAlpha < 0.01) {
     discard; 
  }

  gl_FragColor = vec4(finalColor, finalAlpha);
}
`;

const lightDissolveVertShaderSrc = `
precision highp float;
attribute vec3 aPosition;
attribute vec2 aTexCoord;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
varying vec2 vTexCoord;
void main() {
  vTexCoord = aTexCoord;
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
}
`;

const lightDissolveFragShaderSrc = `
precision highp float;
varying vec2 vTexCoord;
uniform sampler2D uMainTexture;
uniform sampler2D uNoiseTexture;
uniform float uDissolveThreshold;
uniform vec3 uEdgeColor;
uniform float uTime;
void main() {
  vec4 mainColor = texture2D(uMainTexture, vTexCoord);
  float noiseCoordOffset = sin(uTime * 2.5 + vTexCoord.y * 12.0) * 0.015;
  float noiseValue = texture2D(uNoiseTexture, vTexCoord + noiseCoordOffset).r;
  float edgeWidth = 0.2;
  float fadeWidth = 0.15;
  float dissolveFactor = smoothstep(uDissolveThreshold - fadeWidth, uDissolveThreshold + edgeWidth, noiseValue);
  float edgeIntensity = smoothstep(uDissolveThreshold - edgeWidth * 0.6, uDissolveThreshold, noiseValue) *
                        (1.0 - smoothstep(uDissolveThreshold, uDissolveThreshold + edgeWidth * 1.8, noiseValue));
  edgeIntensity *= (0.7 + sin(uTime * 12.0 + noiseValue * 6.0) * 0.3);
  edgeIntensity = max(0.0, edgeIntensity);
  vec3 finalColor = mainColor.rgb * (1.0 - edgeIntensity) + uEdgeColor * edgeIntensity * 3.0;
  finalColor = mix(finalColor, vec3(1.0, 1.0, 0.8), edgeIntensity * 0.7);
  float finalAlpha = mainColor.a * dissolveFactor;
  if (uDissolveThreshold > 0.01 && finalAlpha < 0.01) {
     discard;
  }
  gl_FragColor = vec4(finalColor, finalAlpha);
}
`;

