  if(didWarmup)return;
  didWarmup = true;
  push();
  shader(dissolveShader);
  dissolveShader.setUniform('uWallTexture', wallTexture);
  dissolveShader.setUniform('uNoiseTexture', noiseTexture);
  dissolveShader.setUniform('uDissolveThreshold', 0.5);
  dissolveShader.setUniform('uEdgeColor', [0, 0, 0]);
  dissolveShader.setUniform('uTime', 0);
  translate(1e5, 1e5, 1e5);
  box(cellSize, wallHeight, cellSize);
  resetShader();
