function updatePrestigePowers(dt) {
    if (dt <= 0) return;

    for (let i = 0; i < prestigeItems.length; i++) {
        let item = prestigeItems[i];

        if (item.isActive) {
            item.activeTimer -= dt;
            if (item.activeTimer <= 0) {
                item.isActive = false;
                item.activeTimer = 0;
                item.isOnCooldown = true;
                item.cooldownTimer = item.baseCooldown;

                if (item.id === 0) {
                    wallPassActive = false;
                    consoleCurrentLine = "wallpass 0";
                    handleConsoleCommand(true);
                    consoleCurrentLine = "";
                    if (checkCollision(player.x, player.z)) {
                       teleportToNearestOpenCell();
                    }
                } else if (item.id === 1) {
                    isEnergyShieldActive = false;
                } else if (item.id === 2) {
                    if (sonarSound && sonarSound.isLooping()) {
                        sonarSound.stop();
                    }
                } else if (item.id === 3) {
                    isFlyingWithWings = false;
                    targetFlyHeight = floorY;
                     if (angelWingsSound && angelWingsSound.isLooping()) {
                        angelWingsSound.stop();
                     }
                } else if (item.id === 4) {
                    if (angelFollower && !angelFollower.isDissolving) {
                        angelFollower.isDissolving = true;
                        angelFollower.dissolveProgress = 0.01;
                    }
                }


            }
        } else if (item.isOnCooldown) {
            item.cooldownTimer -= dt;
            if (item.cooldownTimer <= 0) {
                item.isOnCooldown = false;
                item.cooldownTimer = 0;
            }
        }
    }
}

function createEnergyShieldShader() {
    const vs = `
        precision highp float;
        attribute vec3 aPosition;
        attribute vec3 aNormal; 

        varying vec3 var_vertPos;

        uniform mat4 uProjectionMatrix;
        uniform mat4 uModelViewMatrix;

        void main() {
            vec4 modelViewPosition = uModelViewMatrix * vec4(aPosition, 1.0);
            gl_Position = uProjectionMatrix * modelViewPosition;

            var_vertPos = aPosition;
        }
    `;

    const fs = `
        precision highp float;

        varying vec3 var_vertPos; 

        uniform float uTime;
        uniform vec3 uShieldCenter;    
        uniform sampler2D uNoiseTexture; 
        uniform vec3 uBaseColor;       
        uniform float uOpacity;        
        uniform float uWaveFrequency1; 
        uniform float uWaveSpeed1;     
        uniform float uWaveAmplitude1; 
        uniform float uWaveFrequency2; 
        uniform float uWaveSpeed2;     
        uniform float uWaveAmplitude2; 
        uniform float uNoiseInfluence; 

        void main() {

            vec3 worldPos = var_vertPos + uShieldCenter;

            float wave1 = sin(worldPos.y * uWaveFrequency1 + uTime * uWaveSpeed1) * uWaveAmplitude1;

            float wave2 = cos(worldPos.x * uWaveFrequency2 - uTime * uWaveSpeed2) * uWaveAmplitude2;

            float combinedWaveEffect = wave1 + wave2; 

            vec2 noiseCoord = worldPos.xz * 0.05; 
            float noiseVal = (texture2D(uNoiseTexture, noiseCoord).r - 0.5) * 2.0; 
            noiseVal *= uNoiseInfluence; 

            vec3 finalColor = uBaseColor;

            finalColor += uBaseColor * (combinedWaveEffect + noiseVal) * 0.8; 
            finalColor = clamp(finalColor, 0.0, 1.0); 

            float finalAlpha = uOpacity + (combinedWaveEffect + noiseVal) * (uOpacity * 0.5); 
            finalAlpha = clamp(finalAlpha, uOpacity * 0.2, uOpacity * 1.8); 

            gl_FragColor = vec4(finalColor, finalAlpha);
        }
    `;
    let shader = createShader(vs, fs);
    if (!shader) {
        console.error("Failed to create NEW energy shield shader!");
         const vs_fb = `attribute vec3 aPosition; uniform mat4 uProjectionMatrix; uniform mat4 uModelViewMatrix; void main() { gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0); }`;
         const fs_fb = `precision mediump float; uniform vec3 uBaseColor; uniform float uOpacity; void main() { gl_FragColor = vec4(uBaseColor, uOpacity * 0.5); }`;
         shader = createShader(vs_fb, fs_fb);
    }
    return shader;
}

const sonarEnemyVertShaderSrc = `
