const sonarEnemyFragShaderSrc = `
precision highp float;
varying vec2 vTexCoord;

uniform sampler2D uEnemyTexture;
uniform bool uIsSonarActive;
uniform float uTime;
uniform vec3 uSonarColor; 

uniform float uBaseSonarOpacity;
uniform float uPulseAmplitude;
uniform float uPulseFrequency;

uniform float uGridDensity;
uniform float uGridThickness; 
uniform float uGridPulseSpeed;
uniform float uGridPulseAmount;

float calculateGridSharp(vec2 coord, float density, float thickness) {
    float sharpTransition = 0.002; 
    vec2 gridPos = fract(coord * density);
    float clampedThickness = clamp(thickness, 0.001, 0.49); 

    float lowerEdge = clampedThickness;
    float upperEdge = 1.0 - clampedThickness;

    float lineX = smoothstep(lowerEdge, lowerEdge + sharpTransition, gridPos.x) - smoothstep(upperEdge - sharpTransition, upperEdge, gridPos.x);
    float lineY = smoothstep(lowerEdge, lowerEdge + sharpTransition, gridPos.y) - smoothstep(upperEdge - sharpTransition, upperEdge, gridPos.y);

    return 1.0 - clamp(lineX * lineY, 0.0, 1.0); 
}

void main() {
  if (uIsSonarActive) {

    float overlayPulse = (sin(uTime * uPulseFrequency) + 1.0) / 2.0;
    float overlayOpacity = uBaseSonarOpacity + overlayPulse * uPulseAmplitude;
    overlayOpacity = clamp(overlayOpacity, 0.0, 1.0);

    vec4 baseSonarOutput = vec4(uSonarColor, overlayOpacity);

    float gridPulse = (sin(uTime * uGridPulseSpeed + vTexCoord.s * 3.0 - vTexCoord.t * 2.0) + 1.0) / 2.0;
    float currentGridThickness = uGridThickness + gridPulse * uGridPulseAmount;
    currentGridThickness = clamp(currentGridThickness, 0.005, 0.15); 

    float gridMask = calculateGridSharp(vTexCoord, uGridDensity, currentGridThickness);

    vec4 gridLineColor = vec4(uSonarColor * 1.5, overlayOpacity * 1.1); 
    gridLineColor.a = clamp(gridLineColor.a, 0.0, 1.0);

    vec4 finalSonarPassColor = mix(baseSonarOutput, gridLineColor, gridMask);

    gl_FragColor = finalSonarPassColor;

  } else {

    gl_FragColor = texture2D(uEnemyTexture, vTexCoord);
  }
}
`;

function multiplyMatrices(a, b) {
  let result = new Float32Array(16);
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      let sum = 0;
      for (let k = 0; k < 4; k++) {
        sum += a[i + k * 4] * b[k + j * 4];
      }
      result[i + j * 4] = sum;
    }
  }
  return result;
}

