function calculateFrustumPlanes() {
    currentFrustumPlanes = []; 

    let projMatrixSource = _renderer.uPMatrix;
    let viewMatrixSource = _renderer.uMVMatrix;

    if (!projMatrixSource || !viewMatrixSource) {

        currentFrustumPlanes = null; 
        return;
    }

    let projMatrix = (projMatrixSource.mat4 && projMatrixSource.constructor !== Float32Array) ? projMatrixSource.mat4 : projMatrixSource;
    let viewMatrix = (viewMatrixSource.mat4 && viewMatrixSource.constructor !== Float32Array) ? viewMatrixSource.mat4 : viewMatrixSource;

    if (!(projMatrix instanceof Float32Array) || projMatrix.length !== 16 ||
        !(viewMatrix instanceof Float32Array) || viewMatrix.length !== 16) {

        currentFrustumPlanes = null; 
        return;
    }

    let vpMatrix = multiplyMatrices(projMatrix, viewMatrix);
    let m = vpMatrix;

    let planesRaw = [];

    planesRaw.push({ n: [m[3] + m[0], m[7] + m[4], m[11] + m[8]], d: m[15] + m[12] });

    planesRaw.push({ n: [m[3] - m[0], m[7] - m[4], m[11] - m[8]], d: m[15] - m[12] });

    planesRaw.push({ n: [m[3] + m[1], m[7] + m[5], m[11] + m[9]], d: m[15] + m[13] });

    planesRaw.push({ n: [m[3] - m[1], m[7] - m[5], m[11] - m[9]], d: m[15] - m[13] });

    planesRaw.push({ n: [m[3] + m[2], m[7] + m[6], m[11] + m[10]], d: m[15] + m[14] });

    planesRaw.push({ n: [m[3] - m[2], m[7] - m[6], m[11] - m[10]], d: m[15] - m[14] });

    for (let raw of planesRaw) {
        let nx = raw.n[0], ny = raw.n[1], nz = raw.n[2];
        let lengthSq = nx * nx + ny * ny + nz * nz; 

        if (lengthSq > 0.00001) { 
             let length = Math.sqrt(lengthSq);
             currentFrustumPlanes.push({
                 normal: createVector(nx / length, ny / length, nz / length),
                 distance: raw.d / length
             });
        } else {

            currentFrustumPlanes = null;
            return; 
        }
    }

}

function getChunkAABB(chunkX, chunkZ) {
    let minX = chunkX * chunkSize * cellSize;

    let maxX = minX + (chunkSize * cellSize);
    let minY = -wallHeightOffset; 
    let maxY = wallHeight + wallHeightOffset; 
    let minZ = chunkZ * chunkSize * cellSize;

    let maxZ = minZ + (chunkSize * cellSize);

    return {
        min: { x: minX, y: minY, z: minZ },
        max: { x: maxX, y: maxY, z: maxZ }
    };
}

function isBoxInFrustum(aabb, frustumPlanes) {

    if (frustumPlanes === null) {
       return true;
    }

    if (!frustumPlanes || frustumPlanes.length !== 6) {
       return true;
    }

    let corners = [
        createVector(aabb.min.x, aabb.min.y, aabb.min.z),
        createVector(aabb.max.x, aabb.min.y, aabb.min.z),
        createVector(aabb.min.x, aabb.max.y, aabb.min.z),
        createVector(aabb.max.x, aabb.max.y, aabb.min.z),
        createVector(aabb.min.x, aabb.min.y, aabb.max.z),
        createVector(aabb.max.x, aabb.min.y, aabb.max.z),
        createVector(aabb.min.x, aabb.max.y, aabb.max.z),
        createVector(aabb.max.x, aabb.max.y, aabb.max.z)
    ];

    for (let plane of frustumPlanes) {
        let cornersOutsidePlane = 0;
        for (let corner of corners) {

            let distance = plane.normal.dot(corner) + plane.distance;
            if (distance < 0) { 
                cornersOutsidePlane++;
            }
        }

        if (cornersOutsidePlane === 8) {
            return false; 
        }
    }

    return true; 
}
