function createBackroomsWallTexture() {
	const texture = createImage(256, 256);
	texture.loadPixels();
	for (let i = 0; i < texture.width; i++) {
		for (let j = 0; j < texture.height; j++) {
			const shade = random(200, 220); 
			const noiseValue = noise(i * 0.1, j * 0.1);
			const peelEffect = noiseValue > 0.8 ? random(-50, 0) : 0; 
			texture.set(i, j, color(
				constrain(shade + peelEffect, 0, 255),
				constrain(shade - 20 + peelEffect, 0, 255),
				constrain(shade * 0.5 + peelEffect / 2, 0, 255)
			));
		}
	}
	texture.updatePixels();
	return texture;
}

function createBackroomsFloorTexture() {
	const texture = createImage(256, 256);
	texture.loadPixels();
	for (let i = 0; i < texture.width; i++) {
		for (let j = 0; j < texture.height; j++) {
			const noiseValue = noise(i * 0.1, j * 0.1);
			const shade = map(noiseValue, 0, 1, 150, 170); 
			texture.set(i, j, color(
				constrain(shade, 0, 255),
				constrain(shade - 10, 0, 255),
				constrain(shade * 0.5, 0, 255),
				255 
			));
		}
	}
	texture.updatePixels();
	return texture;
}

function createBackroomsCeilingTexture() {
	const texture = createImage(512, 512); 
	texture.loadPixels();

	const gridSize = 33; 
	const cellSizeGrid = texture.width / gridSize;

	for (let i = 0; i < texture.width; i++) {
		for (let j = 0; j < texture.height; j++) {
			const greyShade = random(180, 200); 
			texture.set(i, j, color(greyShade, greyShade, greyShade));
		}
	}

	for (let i = 0; i < gridSize; i++) {
		for (let j = 0; j < gridSize; j++) {
			const isLight = random(1) < 0.15; 
			const startX = i * cellSizeGrid;
			const startY = j * cellSizeGrid;
			const endX = startX + cellSizeGrid;
			const endY = startY + cellSizeGrid;

			for (let x = startX; x < endX; x++) {
				for (let y = startY; y < endY; y++) {
					if (isLight) {
						texture.set(x, y, color(255, 255, 255)); 
					}
				}
			}
		}
	}

	for (let i = 0; i <= gridSize; i++) {
		const x = i * cellSizeGrid;
		const y = i * cellSizeGrid;
		for (let k = 0; k < texture.width; k++) {
			if (x < texture.width) texture.set(x, k, color(100)); 
			if (y < texture.height) texture.set(k, y, color(100)); 
		}
	}

	texture.updatePixels();
	return texture;
}

function createNoiseTexture() {
    let noiseSize = 256;
    let pg = createGraphics(noiseSize, noiseSize);
    pg.loadPixels();
    let noiseScl = 0.1;
    for (let x = 0; x < noiseSize; x++) {
        for (let y = 0; y < noiseSize; y++) {
            let noiseVal = noise(x * noiseScl, y * noiseScl);
            let colorVal = map(noiseVal, 0, 1, 0, 255);
            pg.set(x, y, color(colorVal));
        }
    }
    pg.updatePixels();
    return pg;
}
